window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]=window.__LIBQ["the-gioi-hoan-my"]["q14"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]["cotTruyen"]=[{"chuong":1301,"tieuDe":"Tuyệt Đại Cao Thủ","tomTat":"Vương Trường Sinh và Mạnh Thiên Chính triển khai cuộc quyết đấu ở cấp độ cô đọng Chân Tiên pháp tắc, dù cố thu liễm sức mạnh vẫn làm hư không tan vỡ và một ngọn núi thuộc trận pháp Vương gia nổ tung. Khi uy lực vượt khỏi khả năng khống chế, hai người chuyển lên vực ngoại rồi tiến sâu vào vũ trụ, nơi Bình Loạn Quyết và Nguyên Thần kiếm thai đối đầu cửu chuyển quyền ấn, làm tinh đấu bùng nổ và không gian rạn nứt. Trong lúc kết quả chưa rõ, Vương Đại định bắt Thạch Hạo làm tù binh và cướp Tiên cổ chiến kỳ. Chiến kỳ chứa tinh khí thần của Mạnh Thiên Chính tự giương lên, tái hiện tiếng chém giết Tiên cổ và quét Vương Đại bị thương. Hai tuyệt đại cao thủ sau đó trở về, đồng ý kết thúc cuộc giao tranh bằng thế hòa. Vương Trường Sinh ra lệnh Vương gia không được tiếp tục nhằm vào Thạch Hạo, đồng thời buộc gia chủ đương nhiệm viết pháp chỉ ràng buộc tộc nhân. Mạnh Thiên Chính giữ nguyên điều kiện yêu cầu Vương gia giao đủ các loại thần thảo đặc hữu từ Tiên thổ."},{"chuong":1302,"tieuDe":"Sóng Gió Lớn","tomTat":"Gia chủ đương nhiệm của Vương gia coi việc ký pháp chỉ hòa giải với Thạch Hạo là một sự sỉ nhục, nhưng vẫn phải chấp hành vì các nhân vật cao tầng không ủng hộ việc tiếp tục đối đầu Mạnh Thiên Chính. Trong lúc chờ pháp chỉ, Mạnh Thiên Chính đưa Thạch Hạo vào các dược viên, hái Tử Phủ thảo và cho hắn biết bí mật về đoạn rễ Trường Sinh dược đang dần khôi phục sinh cơ. Trở lại tổ điện, ông đối chất với một huyền tôn của Vương Đại, người thừa nhận từng thúc đẩy chủ trương loại bỏ Thạch Hạo và muốn dựa vào lập trường cứng rắn để tranh vị trí gia chủ. Vương Đại ra tay cứu huyền tôn nhưng bị đánh lui, còn người chống đối bị Mạnh Thiên Chính giết ngay tại chỗ. Pháp chỉ sau đó được chuyển cho một đại giáo dựa vào Thiên Thần Thư Viện và nhanh chóng truyền khắp Vô Lượng Thiên, khiến các thế lực nhận ra Thạch Hạo là người không thể tùy tiện đụng tới. Khi phong ba Vương gia còn lan rộng, một tòa hùng quan lâu đời tại vực ngoại biên cương bất ngờ rạn nứt rồi sụp đổ, báo hiệu một cuộc khủng hoảng lớn hơn."},{"chuong":1303,"tieuDe":"Biên Hoang Báo Nguy","tomTat":"Dư chấn trận chiến giữa Mạnh Thiên Chính và Vương Trường Sinh lan khắp các tộc, khiến nhiều gia tộc nghiêm cấm đệ tử tiếp tục chọc vào Thạch Hạo. Tại Thiên Thần Thư Viện, Yêu Nguyệt vui mừng trước tổn thất của Vương gia và đề nghị thu xếp trận tỷ thí giữa Thạch Hạo với Kim Triển, trong khi Vương Hi muốn rời khỏi cuộc bàn luận. Mạnh Thiên Chính đưa Thạch Hạo trở về sau khi hai người tìm thần dược phụ trợ để luyện hóa Tử Phủ thảo nhưng chưa thu thập đủ, đồng thời tiết lộ Vương Trường Sinh đã cảm nhận nguy hiểm nên muốn bế quan tránh khỏi vòng xoáy. Các trưởng lão tiếp tục thương nghị việc hợp nhất Tiên Viện, Thánh Viện và Thiên Thần Thư Viện, với phương án di chuyển những động phủ Chân Tiên cổ đại thành một căn cơ chung. Đúng lúc ấy, một chiến thuyền đồng thau rách nát và đầy máu từ biên cương xuyên không lao đến thư viện. Mạnh Thiên Chính cứu tỉnh người trung niên chỉ còn nửa thân thể trên thuyền và nhận được tin hùng quan biên cương đã nứt toác, cường giả dị vực đã xuất hiện. Tin dữ khiến mọi người kinh hãi trước khả năng thời đại đen tối nhất đã bắt đầu."},{"chuong":1304,"tieuDe":"Tuyệt Vọng Chi Cảnh","tomTat":"Một người trung niên trọng thương điều khiển nửa chiếc chiến thuyền đồng thau vượt giới tới Vô Lượng Thiên, báo rằng Đại Xích Thiên đã bị tập kích sớm hơn hàng nghìn năm so với dự đoán. Sau khi được Mạnh Thiên Chính và một lão nhân Tiên viện cứu chữa, ông kể cổ thành biên cương được xây bằng tiên cốt đã nứt vỡ, còn toàn bộ tu sĩ bên trong bị Luyện Tiên Hồ nghiền nát và hút lấy Tiên Thiên tinh huyết. Thạch Hạo cùng Thiên Giác Nghĩ nhận ra hung khí này từ dấu ấn từng thấy tại Bất Diệt phong và nhớ tới việc Hạc Vô Song từng mang nó đi thu thập tinh huyết. Khi Luyện Tiên Hồ lui về bên kia giới bích, một bàn tay đen khổng lồ tiếp tục quét sạch sinh linh vùng biên, khiến người báo tin nghi ngờ Dị vực đang dùng máu tế để mở một thông đạo ổn định. Tin dữ khiến mọi người tuyệt vọng vì cửu thiên thập địa không có Chân Tiên để đối đầu sinh linh bất hủ. Mạnh Thiên Chính lập tức ra lệnh thỉnh Tổ Long giác, dùng tiếng kèn xuyên giới bích triệu tập các đại tộc đến cứu viện Đại Xích Thiên. Ông đồng thời trấn an mọi người rằng Dị vực từng bị một nguồn sức mạnh đẩy lui và đời này cũng chưa chắc có thể đứng vững trong thế giới này."},{"chuong":1305,"tieuDe":"Triệu Hoán Chiến Giả","tomTat":"Tiếng kèn từ Tổ Long giác vang khắp chín tầng trời, khơi dậy dũng khí và chiến huyết, đồng thời triệu tập các đại cường tộc tới hội quân. Trước câu hỏi về nguyên nhân dị vực từng rút lui sau đại chiến Tiên cổ, Mạnh Thiên Chính chỉ dùng lời lẽ trấn an sĩ khí và không tiết lộ chân tướng. Thạch Hạo nhận ra sự miễn cưỡng ấy, từ đó suy ngẫm về các tồn tại bí ẩn từng can dự, lời tiên đoán về thời đại hắc ám nhất và manh mối thân thế biết được ba năm trước. Bạch Cốt Sơn, Mục Lan tộc, Từ gia cùng nhiều thế lực khác lần lượt đưa cao thủ và chiến thuyền tới tập kết. Mạnh Thiên Chính tiết lộ rằng nhiều kỳ tài được dự trữ qua các thời đại vẫn còn sống và sẽ đứng ra chống đỡ chiến cuộc, trong khi Thạch Hạo bị từ chối khi xin trực tiếp tham chiến. Sau khi cho phép một bộ phận thế hệ trẻ đi theo quan sát dưới sự bảo vệ của đại trận, Mạnh Thiên Chính hạ lệnh cho toàn bộ đoàn chiến thuyền lập tức tiến về Đại Xích Thiên."},{"chuong":1306,"tieuDe":"Đại Xích Thiên","tomTat":"Trong tiếng kèn Chân Long, hàng ngàn vạn chiến thuyền tiến vào Thiên lộ do tế đàn của Thiên Thần Thư Viện mở ra để chi viện Đại Xích Thiên. Thạch Hạo cùng nhiều thiên tài trẻ tuổi đi cuối đoàn trên một bảo thuyền pha Xích Huyết Tiên Kim, vừa quan sát chiến trường vừa được bảo đảm đường rút lui. Sau khi vượt giới bích, Mạnh Thiên Chính và các lão giả giải thích Đại Xích Thiên vốn thuộc Nguyên Thủy Cổ Giới, từng mang tên Ly Hận Thiên vì nhiều Chân Tiên đã chết trận tại đây. Đoàn quân lần lượt đi qua sào Chân Long bỏ hoang, thi thể Kim Ô tạo thành biển dung nham và nhiều di tích cho thấy sự huy hoàng đã mất của vùng trời này. Tới biên cương, họ phát hiện hàng loạt thành trì và bộ lạc đã bị xóa sổ, với hàng trăm triệu cư dân cùng tu sĩ không còn người sống sót. Dấu vết hắc khí dẫn tới hùng quan xây bằng tiên cốt đã bị đánh nứt, xác nhận sinh linh dị vực vượt qua nơi này để phát động cuộc tàn sát. Một kẻ từ phía dị vực lên tiếng miệt thị quân bản giới và tuyên bố thế giới sắp trở về với Bất Hủ, khiến các cổ thuyền đồng loạt mở sát phạt đại trận và toàn quân chuẩn bị huyết chiến."},{"chuong":1307,"tieuDe":"Đối Kháng","tomTat":"Tại biên cương Đại Xích Thiên, quân vạn tộc đồng loạt kích hoạt phù văn và sát trận trên các cổ thuyền, khiến áo nghĩa của nhiều chủng tộc cộng minh thành vô thượng kinh văn cùng hư ảnh Luân Hồi. Sinh linh Bất Hủ dị vực trong vực sâu dưới phế tích chỉ dùng một bàn tay đen có lân phiến đã phá tan toàn bộ thế công, khiến chiến ý của quân tu sĩ gần như sụp đổ. Hắn tiếp tục dùng chân ngôn nhắc lại thất bại của cường giả kỷ nguyên trước nhằm gieo tuyệt vọng khắp Đại Xích Thiên. Đại trưởng lão quát tỉnh mọi người, xác nhận đối thủ là sinh linh Bất Hủ sống sót từ kỷ nguyên trước và chỉ ra rằng hắn chưa thể hoàn toàn vượt qua giới bích. Các lão giả của Thánh Viện, Tiên viện và Trường Sinh thế gia cùng hưởng ứng, phân tích sự hạn chế do khoảng cách và quy tắc thiên địa để giúp toàn quân lấy lại tinh thần. Bị vạch rõ điểm yếu, sinh linh Bất Hủ nổi giận chộp thẳng về phía Đại trưởng lão, còn ông không né tránh mà quyết định trực diện nghênh chiến để làm gương cho quân sĩ."},{"chuong":1308,"tieuDe":"Khiêu Chiến Bất Hủ","tomTat":"Bất chấp lời can ngăn của Thạch Hạo và sự lo sợ của mọi người, Mạnh Thiên Chính một mình tiến về phía bàn tay đen của sinh linh Bất Hủ đang tàn phá Đại Xích Thiên. Khi bàn tay sắp khép lại nghiền chết ông, Tổ Long giác xuất hiện, được ông dùng tâm thần cùng máu tế luyện rồi hóa thành Chân Long, liên tiếp đâm thủng đối phương. Sinh linh Bất Hủ chuyển sang trực tiếp chộp người điều khiển, nhưng Thập Giới Đồ trải ra như chiến y và tấm thuẫn, chặn rồi đẩy lui đòn đánh để Mạnh Thiên Chính an toàn rút lui. Ông công khai mình đã đạt nửa bước Trường Sinh và khẳng định chỉ vì hoàn cảnh thiên địa không trọn vẹn nên chưa thể thành Tiên, nếu có đủ điều kiện thì mười năm là đủ để giết đối thủ. Mạnh Thiên Chính dùng chiến tích khiến sinh linh Bất Hủ đổ máu để khôi phục sĩ khí và kêu gọi thế hệ trẻ sau này bước vào Tiên Đạo, tiêu diệt địch Dị Vực. Trước lời đe dọa tru diệt toàn bộ huyết thống phản kháng, ông nhận định Dị Vực chưa thể thật sự vượt giới và đang tiến công Đại Xích Thiên vì một mục đích khác. Sự liên kết bước đầu giữa hai giới được ông xem là dấu hiệu cho một cuộc biến đổi thiên địa lớn, đồng thời mở ra cơ duyên mới trên đường thành tiên."},{"chuong":1309,"tieuDe":"Ai Cùng Một Trận Chiến","tomTat":"Bất hủ sinh linh dị vực khinh miệt Cửu Thiên Thập Địa nhưng chân thân của hắn vẫn bị quy tắc thế giới bài xích, buộc bàn tay lớn màu đen phải rút về vực sâu. Trước khi rời đi, hắn đề nghị phái những hậu bối chưa bước vào lĩnh vực bất hủ sang quyết đấu, còn Đại trưởng lão yêu cầu điều tra các bí mật và chiến sử của Đại Xích Thiên. Một nhóm đông sinh linh dị vực sau đó vượt giới, tạo thành trường vực sát khí khiến các cao thủ Cửu Thiên Thập Địa phải hợp sức chống đỡ. Hai bên thống nhất dùng quyết đấu để thăm dò thực lực, và Hướng Phong của Thánh viện đại diện thế hệ trăm vạn năm trước xuất chiến. Sau hơn một trăm chiêu, Hướng Phong bị xé đứt một tay; ông tái sinh cánh tay và tiếp tục tử chiến nhưng cuối cùng bị bóp nát mi tâm, nguyên thần hóa tro. Kẻ chiến thắng tự xưng Đế Đà, tuyên bố chưa dùng thần thuật bản thân và chỉ xếp thứ mười chín trong thế hệ tương ứng của dị vực, khiến phía Cửu Thiên Thập Địa chấn động. Ngay sau đó, một sinh linh dị vực tu hành năm mươi vạn năm tiếp tục khiêu chiến, còn trong đám đông Cửu Thiên Thập Địa có người tự xưng mới tu hành hai mươi năm lên tiếng đáp lời."},{"chuong":1310,"tieuDe":"Sở Sơn Hà","tomTat":"Trước vực sâu hắc ám, Thiên Giác Nghĩ công khai đòi giao chiến với sinh linh Dị Vực để trả huyết thù cho gia đình, nhưng bị ngăn lại vì chưa thành niên. Sở Sơn Hà, thiên tài số một của Tiên Viện cách đây năm mươi vạn năm, bất chấp bệnh căn kéo dài để đứng ra nghênh địch. Sau gần hai trăm chiêu, ông bị tích huyết thần hoàn trói chặt nhưng đã bộc phát Hắc Bạch Sinh Tử Quang, chặt đứt thần hoàn và xé nát đối thủ. Chiến thắng khiến Sở Sơn Hà cạn kiệt tinh khí, phun máu và ngã xuống, phải được người của Tiên Viện khẩn cấp cứu chữa. Phía Dị Vực tiết lộ kẻ vừa chết chỉ từng xếp thứ mười một trong thế hệ cách đây năm mươi vạn năm, khiến áp lực đè nặng lên Cửu Thiên Thập Địa. Ngay sau đó, ba Vương giả Dị Vực thuộc ba lớp tuổi cùng bước ra, đề nghị tổ chức ba cặp quyết đấu. Thiên Giác Nghĩ lập tức muốn xuất chiến nhưng bị Thạch Hạo giữ lại."},{"chuong":1311,"tieuDe":"Thất Bại","tomTat":"Thạch Hạo tiếp tục ngăn Thiên Giác Nghĩ chưa trưởng thành tham gia trận quyết tử, trong khi phía dị vực đưa ra những đối thủ theo từng niên đại tu đạo. Xích Phát Thần Quân được phép xuất chiến và dùng Đại Phần Thiên Công đối đầu Bát Tí Thượng Nhân, nhưng vẫn không thắng nổi tám loại pháp ấn của đối phương. Sau năm trăm chiêu, ông bị xuyên thủng ngực, bẻ gãy cổ rồi đánh nát đầu, đồng thời để lại nghi vấn về huyết mạch có nguồn gốc từ một cường tộc dị vực. Tiếp đó, sinh linh trung niên đầu gai xương chỉ dùng hơn tám mươi chiêu để giết một Chí Tôn đã tu đạo năm vạn năm, khiến cửu thiên thập địa chỉ còn chiến thắng của Sở Sơn Hà sau bốn trận. Trước tình thế bị áp đảo, Thạch Hạo, Tử Nhật Thiên Quân và Thích Cố cùng bước ra tranh quyền giao chiến vì những mục tiêu riêng. Thanh niên dị vực có vảy hình thoi ở mi tâm nhìn thấu Hồng Mông tử khí loại, Âm Dương loại và Cây Thế Giới cây non trong nhóm thiên tài đối diện. Phát hiện ấy khiến hơn mười cường giả trẻ tuổi dị vực đồng loạt kéo tới, coi Lam Tiên, Thập Quan Vương, Đại Tu Đà cùng những người khác là con mồi."},{"chuong":1312,"tieuDe":"Quần Vương","tomTat":"Tại phế tích gần vực sâu màu đen, hơn mười cường giả trẻ tuổi dị vực đồng loạt áp sát và coi tu sĩ Cửu Thiên Thập Địa như con mồi. Tử Nhật Thiên Quân giành lên chiến trường trước, khiến nhiều sinh linh Vương tộc dị vực tranh nhau xuất trận và lựa chọn đối thủ theo hạt giống trong cơ thể họ. Hư Không Vương Thú tấn công Thập Quan Vương, Hoàng Kim Ma Điểu nhắm Lam Tiên, Xà Dạ Xoa chọn Lữ Hồng, còn cô gái tóc bạc nhắm Đại Tu Đà vì Tiên xá lợi. Một sinh linh ngô công áp sát Thạch Hạo nhưng khinh thường hắn vì không phát hiện hoàn mỹ cổ chủng, chỉ coi Thiên Giác Nghĩ trên vai hắn là mục tiêu quý giá. Qua cách đối phương chọn người, Thạch Hạo nhận ra dị vực nắm giữ bí thuật tra xét cổ chủng được truyền từ thời Tiên cổ và có thể đã chuẩn bị phương pháp khắc chế. Cảm thấy tình thế nguy hiểm, hắn chủ động phóng mười mấy đạo bảo thuật về phía toàn bộ cường giả dị vực, trực tiếp khơi mào một trận quần chiến."},{"chuong":1313,"tieuDe":"Tổ Tiên Tử Chiến Phương Thức","tomTat":"Thạch Hạo chủ động khiêu khích hơn mười Vương giả dị vực, thu hút hỏa lực để giúp những người mang cổ chủng ổn định thế trận và suy nghĩ cách ứng phó nguy cơ bị khắc chế. Trước cuộc vây công của Ngân Dạ Xoa, Hư Không Vương Thú, Hoàng Kim Ma Điểu cùng các đối thủ khác, hắn hóa thành hồ quang điện né đòn hợp kích và quyết giết địch để báo thù cho những tiền bối vừa tử trận. Đại Tu Đà, Thạch Nghị và Thích Cố định ra tay tương trợ, nhưng Mạnh Thiên Chính xuất hiện hóa giải công kích rồi đề nghị tiếp tục hình thức đấu đơn nhằm tránh tổn thất vô ích. Ba sinh linh cổ xưa dị vực đối đầu với ông, dùng lời khích tướng và sự đại bại thời cổ để ép thế hệ trẻ cửu thiên thập địa nhận chiến. Khi Thạch Hạo, Thích Cố, Tiểu Thiên Vương cùng nhiều thiên tài đều không chịu lùi bước, phía dị vực đề nghị dùng Tiên Quy Giáp Phiến phân định đối thủ theo phương thức tử chiến của tổ tiên. Trưởng lão Tiên Viện, Mạnh Thiên Chính và các tộc chủ Trường Sinh thế gia cuối cùng chấp thuận, bởi tiếp tục che chở mà khiến hậu bối mất tín niệm cũng không còn ý nghĩa. Cuộc đối đầu vì thế được nâng thành canh bạc liên quan đến tộc vận và giới vận, trong khi Mạnh Thiên Chính kín đáo gửi kỳ vọng chiến thắng vào Thạch Hạo. Sau khi hai phía thống nhất quy tắc, sinh linh cổ xưa dị vực tuyên bố đại quyết đấu sắp bắt đầu."},{"chuong":1314,"tieuDe":"Nộ Huyết Sôi","tomTat":"Thế hệ trẻ dị vực khơi lại chiến tích của tổ tiên thời Tiên cổ và liên tục khích bác Cửu Thiên Thập Địa bước vào cuộc đấu sinh tử. Sau khi hai bên tranh luận về số trận, các kỳ tài sở hữu hoàn mỹ hạt giống, ba đạo tiên khí và truyền nhân hàng đầu Thánh Viện đều tiến lên ứng chiến. Tiên Quy Giáp Phiến làm hỗn loạn thiên cơ rồi chọn Xà Dạ Xoa và Huyền Côn làm cặp đối thủ đầu tiên. Huyền Côn nâng trạng thái lên đỉnh cao, dùng ba đạo tiên khí hóa thành thần kiếm nhưng vẫn không thể phá được thân thể được khói xám bảo vệ của Xà Dạ Xoa. Sau hơn một trăm hiệp, Xà Dạ Xoa dùng cánh bạc giam cầm Huyền Côn, lấy đuôi rắn xuyên tim, phá nguyên thần và khiến hắn hình thần đều diệt. Kẻ thắng tuyên bố tiếp tục ở lại chiến trường và yêu cầu đối thủ kế tiếp phải có hoàn mỹ bảo chủng. Trước khi mai rùa chọn cặp mới, Thạch Hạo bước ra ngăn lại, đề nghị một mình đánh ba, thậm chí đánh mười cao thủ dị vực."},{"chuong":1315,"tieuDe":"Tàn Khốc Tử Chiến","tomTat":"Chứng kiến Huyền Côn cùng nhiều tiền bối lần lượt chết trận, Thạch Hạo xin phá lệ đối đầu Xà Dạ Xoa và thế hệ trẻ Dị vực nhưng bị bác bỏ vì quy củ giao chiến không thể thay đổi. Mạnh Thiên Chính hóa giải đòn uy hiếp thần hồn nhắm vào đệ tử và cảnh cáo đối phương không được tập sát hắn. Tiên Quy Giáp Phiến chọn Lữ Hồng của Lữ gia giao chiến với Hoàng Kim Ma Điểu sau khi Xà Dạ Xoa bị gọi trở lại. Lữ Hồng dựa vào tánh mạng chi loại và sinh cơ mạnh mẽ để chiến đấu suốt chín trăm hiệp, nhưng cuối cùng bị Ma Âm xuyên thủng mi tâm và hơn trăm lông vũ đâm khắp cơ thể. Hoàng Kim Ma Điểu lấy cổ chủng khỏi thi thể nàng rồi dùng chú ngữ ngăn hạt giống chạy thoát. Ngay sau đó, giáp phiến của Hoàng Kim Ma Điểu hiện sắc đỏ cùng chữ viết báo hiệu chết ký, tử cục, khiến các sinh linh cổ xưa Dị vực vội ra lệnh nàng tránh né. Khi đối phương hoảng sợ hỏi ai mang họ Thạch, Thạch Hạo lên tiếng nhận mình và chuẩn bị cho trận chiến có thể sắp tới."},{"chuong":1316,"tieuDe":"Liên Tiếp Chết Trẻ","tomTat":"Người Lữ gia đoạt lại thi thể Lữ Hồng nhưng nàng đã mất hoàn toàn sinh cơ, khiến Thạch Hạo căm giận và muốn lập tức ra trận. Tiên Quy Giáp Phiến báo điềm chết cho Hoàng Kim Ma Điểu, buộc nàng rút lui theo lệnh triệu hồi của cổ sinh linh Dị vực, còn mảnh giáp phiến chọn người lần lượt lướt qua Thạch Hạo, Thạch Nghị và Tần Hạo. Một thiên tài Thánh Viện cuối cùng được chọn đối đầu Ngân Linh của Bạch Ngân Vương tộc, nhưng bị nàng dùng một ngón tay xuyên thủng trán sau hơn một trăm chiêu. Ngân Linh công khai thân phận và chế nhạo tuổi trẻ Chí Tôn của cửu thiên thập địa. Ở trận tiếp theo, Tử Nhật Thiên Quân dốc toàn lực dùng Tử Khí Đông Lai cùng Hồng Mông Tử Khí chủng giao chiến với Đường Ngô. Đường Ngô dùng cổ chú quấy nhiễu cổ chủng, thi triển ô quang bản mệnh áp chế đối thủ rồi chém Tử Nhật Thiên Quân thành nhiều đoạn và cướp lấy Hồng Mông Tử Khí chủng. Cửu thiên thập địa vì thế tiếp tục thua trận thứ tư và mất thêm một tuổi trẻ Vương giả."},{"chuong":1317,"tieuDe":"Thạch Hạo Nộ Xuất","tomTat":"Cửu Thiên Thập Địa liên tiếp mất bốn Vương giả trẻ tuổi, khiến toàn quân bi phẫn và nhận rõ ưu thế áp đảo của Dị Vực. Sau khi giết Tử Nhật Thiên Quân, Đường Ngô nhận điềm đại cát từ Tiên Quy giáp phiến, còn Hồng Mông Tử Khí chủng của người chết bị một lão giả Dị Vực thu giữ. Giáp phiến kế đó chọn Tần Hạo, khiến Dị Vực phát hiện chiến y có thể luyện từ mảnh vỡ Tiên Vương giáp và khối Chí Tôn cốt còn sinh cơ trong cơ thể hắn. Biết em trai không phải đối thủ của Đường Ngô, Thạch Hạo buộc Tần Hạo kích hoạt Chí Tôn cốt đồng nguyên với mình, làm khí tức hai người tương tự và khiến giáp phiến chuyển sang chọn hắn. Tần Hạo nghe lời lui về, còn Thạch Hạo bước vào chiến trường và nhận lời báo thù cho Tử Nhật Thiên Quân. Trước sự khiêu khích của Đường Ngô, hắn tuyên bố sẽ giết toàn bộ thế hệ trẻ Dị Vực. Sát khí và lời tuyên chiến của Thạch Hạo dẫn động sấm chớp cùng nhiều tòa Lôi Trì, tạo thành thiên địa kỳ cảnh trước khi trận chiến bắt đầu."},{"chuong":1318,"tieuDe":"Xé Địch Thủ","tomTat":"Giữa chiến trường hai giới phủ kín lôi điện, Đường Ngô cùng các Vương giả trẻ tuổi Dị Vực tiếp tục miệt thị Cửu Thiên Thập Địa, còn Thạch Hạo tuyên bố sẽ giết từng kẻ dám ra trận. Ngay sau khi Đường Ngô khoe rằng thiên vận đứng về phía mình, ráng lành trên mảnh Tiên Quy Giáp Phiến tương ứng với nó đột ngột biến mất. Đường Ngô dùng cánh tay đường lang hóa thiên đao thăm dò, nhưng quyền ấn mang lôi quang của Thạch Hạo đỡ được đòn đánh mà không khiến hắn lùi bước. Nó lập tức tung sát chiêu từng giết Tử Nhật Thiên Quân, phối hợp ô quang cầm cố với thiên đao chém đầu đối thủ. Thạch Hạo khai mở tiềm lực theo con đường lấy thân làm chủng, dùng thần hoàn tiêu diệt ô quang rồi dung hợp phù văn Côn Bằng, Lôi Đế và Liễu Thần vào tay phải. Trong lần đối đầu trực diện, hắn dùng chưởng đao chặt đứt cánh tay phải hóa thiên đao của Đường Ngô, khiến sĩ khí phía Cửu Thiên Thập Địa bùng lên. Đường Ngô quay người tháo chạy và dùng thân rết phản kích, nhưng Thạch Hạo bắt lấy đuôi, kéo nó trở lại rồi xé đứt thân thể; đến cuối chương, đối thủ vẫn còn nhuốm máu gào thét nên chưa được xác nhận đã chết."},{"chuong":1319,"tieuDe":"Người Kế Tiếp","tomTat":"Đường Ngô bị Thạch Hạo xé đứt thân thể nhưng kịp tự chém bỏ một đoạn mình để thoát chết, sau đó uống tổ tiên tinh huyết và tái tạo toàn thân. Dù chuyển sang dùng kỹ xảo cùng đao khí từ hai cánh tay bọ ngựa, hắn vẫn bị Thạch Hạo dùng quyền ấn áp đảo, đánh nổ thân thể và phá nát đầu lâu. Chiến thắng này giúp Cửu Thiên Thập Địa giành lại khí thế sau chuỗi thất bại, còn thư đồng của Tử Nhật Thiên Quân quỳ lạy cảm tạ người đã báo thù cho chủ. Thạch Hạo không rời đấu tràng mà lập tức gọi đối thủ kế tiếp, khiến Tiên mai rùa mảnh chọn một quái nhân có sừng dê và mười hai đôi cánh tay. Quái nhân triệu hồi ma tường đen nhuộm máu bằng tổ thuật, nhưng Thạch Hạo phối hợp liễu cành hóa xích thần, lôi đình hỗn độn và pháp môn Côn Bằng để phá hủy bức tường. Hắn tiếp tục tung một quyền đánh nổ đối thủ thứ hai rồi công khai tuyên bố sẽ lần lượt thanh toán toàn bộ mười vương giả Dị vực."},{"chuong":1320,"tieuDe":"An Lan","tomTat":"Sau khi đánh chết Đường Ngô và vương giả mang bản thể hoàng kim sơn dương, Thạch Hạo giao Tào Vũ Sinh cùng con kiến vàng thu giữ thi thể rồi tiếp tục khiêu chiến Dị vực. Hai chiến thắng liên tiếp của Hoang khôi phục sĩ khí cho tu sĩ Cửu Thiên Thập Địa, trong khi các vương giả trẻ tuổi Dị vực phẫn nộ và Tiên Quy Giáp Phiến chọn thanh niên áo trắng Triển Phong làm đối thủ kế tiếp. Triển Phong tiết lộ mình mang một phần tư chân huyết An Lan vì ngoại tổ mẫu xuất thân từ dòng họ này. Khi Thạch Hạo nói tới họ An Lan, sát khí kinh thiên và một cây trường thương vàng hiện ra giữa hư không; Đại trưởng lão xác nhận đó là sức mạnh tên thật của một tồn tại vô thượng vẫn còn sống. Thạch Hạo nhận ra cây thương chính là binh khí từng xuyên thủng Thiên Giác Nghĩ đời trước trong dấu ấn lưu tại Tiên phủ dưới lòng đất Thiên Thần Thư Viện. Dù biết uy thế đáng sợ của An Lan tộc, hắn vẫn tuyên bố sẽ giết cả người mang huyết thống thuần chủng, khiến Triển Phong nổi giận và lập tức ra tay."},{"chuong":1321,"tieuDe":"Chân Huyết Bại","tomTat":"Triển Phong mở đầu trận đấu bằng tay áo chứa sức mạnh tinh thần, nhưng Thạch Hạo dùng Côn Bằng pháp đánh tan thế công. Dựa vào một phần tư chân huyết An Lan, Triển Phong triệu ra hàng vạn trường thương vàng, song chúng lần lượt bị Bảo thuật Lôi Đế và duy nhất động thiên phá hủy. Trong cuộc đối đầu nhục thân tiếp theo, bàn tay Triển Phong bị đánh vỡ và hắn phải dùng thần đan để hồi phục. Hắn tiếp tục kích hoạt hoa văn trường thương do chân huyết An Lan thai nghén, nhưng Thạch Hạo vận dụng thành quả lĩnh hội Bất Diệt Kinh, tay không bắt lấy rồi bẻ gãy cây thương. Chân huyết bị phá hỏng khiến Triển Phong hoàn toàn thất thế, mất một cánh tay và cuối cùng bị đánh cho thân thể chia năm xẻ bảy. Sau khi giết Triển Phong, Thạch Hạo lập tức gọi đối thủ kế tiếp, khiến các vương giả trẻ tuổi Dị vực kinh hãi trước ý định một mình tiếp tục khiêu chiến quần vương."},{"chuong":1322,"tieuDe":"Địa Tam Tiên","tomTat":"Sau ba chiến thắng liên tiếp, uy thế của Thạch Hạo khiến các Vương giả trẻ tuổi Dị Vực không còn dám xem thường, nhưng một thân ảnh gần vực sâu hắc ám đã lên tiếng khơi lại chiến ý của họ. Tiên Quy giáp phiến chưa chọn đối thủ mới vì Thạch Hạo có quyền nghỉ ngơi hoặc rút lui, song hắn vẫn đứng nguyên giữa chiến trường chờ người tiếp theo. Hai bên sau đó đấu khẩu về thất bại của Cửu Thiên Thập Địa trong thời Tiên Cổ, còn Thạch Hạo tuyên bố mối nhục ấy sớm muộn cũng được đòi lại. Để đáp trả sự sỉ nhục, hắn cho mang tàn thể Đường Ngô và sơn dương vàng tới, kéo thêm tàn thể Triển Phong rồi nấu cả ba ngay trước mặt hai phe. Thạch Hạo đặt tên món ăn là Địa Tam Tiên, khiến phe Cửu Thiên Thập Địa phấn chấn còn các Vương giả Dị Vực vô cùng phẫn nộ. Sau khi nhận thần tửu từ một trưởng lão Trường sinh thế gia, hắn gọi ba chiến lợi phẩm chỉ là món khai vị và tuyên bố sẽ tiếp tục giết từng Vương giả Dị Vực tới khi gom đủ thập toàn đại bổ."},{"chuong":1323,"tieuDe":"Hỏa Nham Vương","tomTat":"Thạch Hạo công khai uống rượu, ăn thịt ba Vương giả Dị Vực và đặt tên món ăn là “Địa Tam Tiên”, khiến đối phương phẫn nộ vì lo nỗi nhục này sẽ lưu truyền rộng rãi. Khi thời gian nghỉ kết thúc, Tiên Quy giáp phiến chọn Hỏa Nham Vương làm đối thủ tiếp theo của hắn. Hỏa Nham Vương nung chảy đại địa thành biển dung nham, che giấu chân thân và tiếp dẫn Thái Dương chi tinh để tấn công. Thạch Hạo dùng động thiên hộ thể, lôi đình áp chế biển lửa rồi thi triển pháp môn Côn Bằng ngăn cách nguồn sức mạnh mặt trời. Hắn bức Hỏa Nham Vương khỏi dung nham và đánh nổ chân thân, hoàn thành chiến thắng thứ tư liên tiếp. Sau trận đấu, Thạch Hạo tiếp tục xem huyết nhục đối phương là nguyên liệu món ăn rồi công khai thách đấu đồng thời Xà Dạ Xoa và Hoàng Kim Ma Điểu, đẩy hai Vương giả vào tình thế khó thể thoái lui."},{"chuong":1324,"tieuDe":"Liền Giết","tomTat":"Sau bốn chiến thắng, Thạch Hạo muốn khiêu chiến Xà Dạ Xoa và cô gái Hoàng Kim Ma Điểu, nhưng Tiên Quy Giáp lại chọn Song Tử Vương làm đối thủ tiếp theo. Song Tử Vương dùng hai đầu ngâm thần chú quấy nhiễu hoàn mỹ cổ chủng, khiến đạo chủng trong cơ thể Lam Tiên và những người quan chiến xao động, đồng thời phối hợp sức mạnh quang ám tấn công Thạch Hạo. Thạch Hạo phá tan các lớp công kích, đánh nổ thân thể đối phương rồi bắt và tiêu diệt Nguyên Thần, giành chiến thắng thứ năm liên tiếp. Hắn tiếp tục dùng lời lẽ từng được đối phương sử dụng để sỉ nhục Huyền Côn, ép Xà Dạ Xoa phải tái chiến vì thể diện của dị vực. Xà Dạ Xoa vận dụng cánh bạc tạo trường vực cầm cố, dùng đuôi rắn và thần chú giao chiến, nhưng Thạch Hạo phá hết công kích, dùng hai tay được Bất Diệt Kinh cường hóa chặt đuôi rồi đánh chết hắn bằng một quyền xuyên xương trán. Chiến thắng thứ sáu liên tiếp khiến các vương giả trẻ tuổi dị vực trở nên nghiêm nghị. Cô gái Hoàng Kim Ma Điểu sau đó nhận lời khiêu chiến, nhưng ngay đòn đầu đã bị hàm nghĩa Bất Diệt Kinh làm lông vàng héo rụng, hiện nguyên hình ma cầm và chịu thương."},{"chuong":1325,"tieuDe":"Cái Thứ Bảy","tomTat":"Hoàng Kim Ma Điểu dùng bản thể áp sát Thạch Hạo nhưng bị đánh rụng nhiều lông vàng, sau đó chuyển sang chiêu hàng hắn bằng vinh hoa, Tổ thuật và Trường Sinh dược. Nàng tuyên bố Dị Vực sắp tiến công quy mô lớn, đồng thời cho rằng Tội Huyết hậu nhân là con cháu của những kỳ tài từng quy thuận Dị Vực, khiến Thạch Hạo, Thạch Nghị và Tần Hạo chấn động. Thạch Hạo vẫn tin tổ tiên Thạch tộc không phải tội nhân và bác bỏ lời mời gọi. Hoàng Kim Ma Điểu thi triển mười vạn lông vàng hóa thần tiễn, nhưng Thạch Hạo dùng Bảo thuật Lôi Đế tạo vòng xoáy phá hủy toàn bộ. Nàng tiếp tục thiêu đốt Tổ huyết và sinh mệnh bản nguyên để phát ra chín tiếng ma âm, khiến mi tâm Thạch Hạo nứt chảy máu và nguyên thần rơi vào sát cục. Thạch Hạo mặc niệm Nguyên Thủy Chân Giải để thủ hộ nguyên thần, đẩy lui tử khí và phục hồi thương thế. Khi Hoàng Kim Ma Điểu đã kiệt quệ, hắn dùng một chỉ xuyên thủng mi tâm nàng rồi tuyên bố đây là đối thủ thứ bảy."},{"chuong":1326,"tieuDe":"Bễ Nghễ Dị Vực","tomTat":"Sau khi liên tiếp giết bảy vương giả Dị vực, Thạch Hạo đứng một mình giữa cổ chiến trường và đòi đối thủ tiếp theo, khiến phe bên kia phẫn nộ nhưng chưa ai dám lập tức xuất chiến. Người Lữ gia cảm tạ hắn đã giết Hoàng Kim Ma Điểu để báo thù cho Lữ Hồng, trong khi hai phe cùng nhắc tới sự đáng sợ của huyết thống An Lan tộc. Trong khoảng nghỉ, Thạch Hạo thu thi thể Hoàng Kim Ma Điểu và Xà Dạ Xoa làm thức ăn, cố ý làm nhục đối phương rồi lên án những cuộc tàn sát mà Dị vực từng gây ra cho Cửu Thiên Thập Địa. Cường giả trung niên Sắc Đức tuyên bố thiên vận thuộc về Dị vực, còn Thạch Hạo hẹn ngày sau sẽ dùng một tay bóp chết hắn. Sắc Đức định vượt giới ra tay nhưng bị giới bích và quy tắc phản phệ, sau đó phải lui lại trước lời cảnh cáo của Mạnh Thiên Chính. Thạch Hạo tiếp tục cho phép ba đối thủ còn lại cùng ra trận và công khai vạch ra rằng Dị vực đang che giấu một kế hoạch khác sau những cuộc quyết đấu của thế hệ trẻ."},{"chuong":1327,"tieuDe":"Quét Ngang","tomTat":"Thạch Hạo tiếp tục khiêu chiến các vương giả dị vực, thậm chí chấp nhận nhiều người liên thủ để dùng một trận đại thắng củng cố lòng tin cho Cửu Thiên Thập Địa. Tiên Quy Giáp lựa chọn một cao thủ trẻ tuổi của Kim Giáp tộc, sinh linh hỗn huyết sở hữu mai rùa hoàng kim có sức phòng ngự kinh người. Đối thủ dùng Long Quy trảo, Nghiệt Long giác và tổ thuật công thủ hợp nhất, nhưng Thạch Hạo vận dụng Bất Diệt Kinh đánh nứt mai rùa rồi giết chết hắn. Đối thủ thứ chín là nam tử có vảy ở mi tâm, hậu duệ của một kỳ tài Cửu Thiên Thập Địa từng chủ động đến góp sức cho dị vực. Sau hơn ba trăm hiệp, Thạch Hạo vượt qua thần quang từ vảy mi tâm và đánh toàn thân đối thủ thành sương máu, hoàn thành chín chiến thắng liên tiếp. Khi chỉ còn một suất giao chiến, Hạc Vô Song vượt qua vực sâu hắc ám và bước vào chiến trường. Thiên Giác Nghĩ kinh động nhận ra hắn, còn các vương giả dị vực lập tức trở nên cuồng nhiệt và tin rằng Hoang sẽ bị giết."},{"chuong":1328,"tieuDe":"Hạc","tomTat":"Một nam tử tóc vàng bước ra từ vực sâu dưới phế tích cổ thành ở biên cương Đại Xích Thiên và được các vương giả trẻ tuổi Dị vực đồng loạt hành đại lễ. Thiên Giác Nghĩ nhận nhầm hắn là Hạc Vô Song, kẻ đã giết huynh trưởng và tỷ tỷ của mình, nên lập tức cuồng hóa định báo thù. Thạch Hạo kịp giữ nó lại, dùng đạo âm và điểm vào mi tâm để giúp nó tỉnh táo, nhận ra người mới đến chỉ là hậu duệ của Hạc Vô Song. Nam tử tóc vàng xác nhận Hạc Vô Song là gia tổ, còn phe Dị vực tiết lộ nhân vật này đã trở thành Bất Hủ thuộc hàng cấm kỵ. Thiên Giác Nghĩ vẫn liên tiếp gọi thẳng tên Hạc Vô Song, khiến binh hồn đại kích quấn hỗn độn khí thức tỉnh và hiện thế với uy thế trấn áp thiên địa. Qua phản ứng của binh khí, Thạch Hạo nhận định Hạc Vô Song đã trở thành họa lớn tuyệt thế nhưng vẫn kém cổ tổ An Lan một bậc. Trước lời thỉnh cầu giết Thạch Hạo của cô gái tóc bạc, hậu duệ Hạc gia không lập tức ra tay mà tuyên bố mình đến để công bố một chuyện cực kỳ quan trọng."},{"chuong":1329,"tieuDe":"Người Cuối Cùng","tomTat":"Hạc Tử Minh tiếp tục trì hoãn việc công bố một tin tức quan trọng, khiến phía Cửu Thiên Thập Địa lo ngại đại biến bất lợi sắp xảy ra. Vì đến chiến trường quá muộn, hắn không thể được Tiên mai rùa chọn tham gia mười trận đánh cược, nhưng tuyên bố sẽ tự tay giết Thạch Hạo nếu đối phương còn đứng vững sau đó. Mạnh Thiên Chính và người của các Trường Sinh thế gia liên hệ sự xuất hiện của Hạc Tử Minh với Luyện Tiên Hồ từng phá thành cổ ở biên cương Đại Xích Thiên, từ đó nghi Hạc gia có liên quan đến biến cố. Thiên Giác Nghĩ thách đấu Hạc Tử Minh để báo thù cho anh chị nhưng bị từ chối vì chưa trưởng thành, còn Thạch Hạo nhận lời sẽ thay nó đối phó hậu nhân kẻ thù. Tiên mai rùa sau đó chọn Ngân Linh của Bạch Ngân Vương tộc làm đấu thủ thứ mười, buộc nàng phải ra trận dù biết mình khó thắng. Hạc Tử Minh lấy một lượng cổ tổ chân huyết chưa tới nửa giọt, pha với dược dịch rồi viết chữ “Giết” lên lòng bàn tay Ngân Linh, giúp nàng lấy lại tự tin. Ngân Linh bước vào chiến trường để bảo vệ uy nghiêm Dị vực, còn Thạch Hạo coi mọi thủ đoạn của đối phương là vô dụng và chủ động xuất thủ mở màn trận chiến cuối."},{"chuong":1330,"tieuDe":"Mười Trận Chiến Toàn Thắng","tomTat":"Ngân Linh của Bạch Ngân Vương tộc chủ động xuất chiến, hóa vật chất chung quanh thành dòng Bạch Ngân để ăn mòn chiến trường và vây giết Thạch Hạo. Thạch Hạo dùng Lôi Đế bảo thuật áp chế nhưng vẫn cố ý né tránh nhằm quan sát uy lực của nửa giọt cổ tổ chân huyết được bố trí trong lòng bàn tay đối thủ. Hạc Tử Minh tiếp tục truyền thần chú, khiến chữ “Giết” do chân huyết tạo thành tự động truy đuổi Thạch Hạo như hình với bóng. Sau khi thăm dò đầy đủ, Thạch Hạo rút Đại La Tiên Kiếm chém tan chữ “Giết” rồi chặt đứt bàn tay chứa chân huyết của Ngân Linh. Hạc Tử Minh định cứu nàng nhưng không dám can thiệp vì kiêng dè mảnh giáp Tiên mai rùa. Thạch Hạo chém đầu, xuyên thủng mi tâm và diệt Nguyên Thần Ngân Linh, qua đó hoàn thành mười trận toàn thắng trước mười cao thủ Dị vực. Sau chiến thắng, hắn thu bàn tay bị chặt vào một đỉnh nhỏ bằng bạch ngọc và phong ấn lại."},{"chuong":1331,"tieuDe":"Đại Loạn","tomTat":"Thạch Hạo tiếp tục khiêu khích Hạc Tử Minh, khiến hậu duệ Hạc gia nổi giận và tuyên bố sẽ đánh giết hắn. Hai người đối quyền dữ dội, làm trời đất nứt vỡ nhưng vẫn bất phân thắng bại và đều không bị thương. Hạc Tử Minh sau đó triển khai Bất Diệt Kinh, còn Thạch Hạo nhận ra mình đang nắm giữ kinh văn toàn diện hơn. Trận chiến chưa kịp tiếp diễn thì tin Biên Hoang đã bị phá một tầng quan truyền tới, khiến Hạc Tử Minh dừng tay và các cường giả Dị vực rút về vực sâu. Phe Cửu Thiên Thập Địa nhận định Dị vực đang đồng thời uy hiếp Biên Hoang và Đại Xích Thiên biên cương để buộc họ chia lực lượng. Mạnh Thiên Chính quyết định mang Thập Giới Đồ tới Biên Hoang, đồng thời để Tiên Vương quấn vải liệm ở lại trấn giữ chiến trường Đại Xích Thiên."},{"chuong":1332,"tieuDe":"Không Tầm Thường","tomTat":"Tin Biên Hoang nguy cấp truyền tới Đại Xích Thiên khi dị vực bất chấp tổn thất mở cuộc tiến công quy mô lớn nhằm phá quan. Thạch Hạo muốn trở về ba ngàn đạo châu thăm người thân nhưng kìm nén tư tình, trong khi chín phần mười đại quân Cửu Thiên mang Thập Giới Đồ và Tổ Long kèn lệnh lên đường cứu viện qua cánh cửa không gian do bạch cốt tế đàn mở ra. Mạnh Thiên Chính cùng các tu sĩ trẻ được giữ lại trấn thủ Đại Xích Thiên, còn Hạc Tử Minh trước khi rút đi đã hạ chiến thư hẹn lần sau tự tay chém Thạch Hạo. Sau khi đại quân rời đi, chiến trường trở nên quạnh quẽ và tinh thần mọi người sa sút vì nhớ tới những thiên tài đã chết trận, chỉ còn chiến tích mười trận toàn thắng của Thạch Hạo là niềm an ủi. Một lão nhân dị vực thuộc nhóm cường giả mạnh nhất dưới Bất Hủ bước ra từ vực sâu, công khai kế hoạch hai mặt giáp công và úp mở về bí mật của Đại Xích Thiên. Lão dựng tế đàn hướng về vực sâu, triệu tập hơn trăm cường giả hóa thạch sống cùng tụng cổ kinh, buộc Mạnh Thiên Chính phải dựng Thiết Huyết Chiến Kỳ che kín bầu trời để bảo vệ toàn bộ quân lưu thủ."},{"chuong":1333,"tieuDe":"Cổ Tổ Anh Linh","tomTat":"Hàng trăm lão nhân Dị vực tụng chiêu hồn kinh quanh tế đàn trên hắc ám vực sâu, khiến vô số quỷ ảnh và anh linh hội tụ. Mạnh Thiên Chính dùng Thiết Huyết Chiến Kỳ bảo vệ đoàn người rồi công kích một đoàn hồn hỏa thần thánh, nhưng Luyện Tiên Hồ của Dị vực xuất hiện ngăn cản. Đoàn hồn hỏa nhập vào nhãn cầu còn sót lại của Lạc Ma, giúp tàn hồn vị vô thượng cổ tổ này tạm thời thức tỉnh và tỏa khí thế chấn động biên cương Đại Xích Thiên. Lạc Ma tiết lộ đối thủ từng giao chiến với mình cũng đã chết, còn các lão nhân Dị vực dò hỏi chuyện năm xưa để đánh giá lực lượng Cửu Thiên Thập Địa. Sau khi biết hậu duệ vẫn hưng thịnh và được Du Đà bảo hộ, Lạc Ma nhận ra An Lan cùng Du Đà đã tính toán việc sử dụng phần tàn hồn cuối cùng của mình. Ông vẫn chấp thuận mở phong ấn cổ giới, khiến nhãn cầu nứt vỡ, máu bất hủ cùng tàn hồn hóa thành dấu ấn tọa độ xuyên thủng hỗn độn."},{"chuong":1334,"tieuDe":"Phong Ấn","tomTat":"Nhãn cầu, tàn hồn và ngũ sắc chân huyết còn sót lại của Lạc Ma hóa thành bất hủ huyết tinh, xuyên thủng hỗn độn và mở ra con đường tới một cổ giới bị che giấu. Mạnh Thiên Chính dùng Tiên Vương quấn vải liệm bảo vệ những người bên cạnh, đồng thời nhận ra đặc tính đáng sợ của ngũ sắc chân huyết. Khi cự bi màu đen cao mười vạn trượng hiện ra chắn đường, chiến huyết Lạc Ma tự ngưng thành hình người, kết pháp ấn và liên tiếp hóa ra binh khí công kích. Chứng kiến bản năng chiến đấu vẫn tồn tại sau cái chết của một Chí Cường giả, Mạnh Thiên Chính nhìn thấy một con đường mới và quyết định tương lai sẽ thử xông vào dù phải đối diện tình thế thập tử vô sinh. Sau nhiều đợt công phá, ngũ sắc chân huyết bành trướng, nổ tung rồi bùng cháy tiêu tan, khiến người Dị vực thoạt đầu tưởng kế hoạch đã thất bại. Tuy nhiên, cự bi ngay sau đó nứt ra và chảy máu, còn không gian hỗn độn quanh cổ giới cũng xuất hiện khe hở cùng thần quang, xác nhận phong ấn đã bị kích nứt."},{"chuong":1335,"tieuDe":"Cổ Địa Lưu Huyết","tomTat":"Hơn mười lão giả Dị vực vượt Hắc Ám Thâm Uyên để thăm dò Cổ Giới trong hỗn độn, nhưng bị Mạnh Thiên Chính dùng Thiết Huyết Chiến Kỳ chặn đánh và Luyện Tiên Hồ đứng ra đối kháng. Khi một lão giả thu huyết trên Hắc Sắc Thạch Bia vào đồng đỉnh, bia đá trút huyết vũ, xuyên phá pháp khí và thiêu diệt toàn bộ toán tiên phong. Dị vực vẫn quyết định mang Luyện Tiên Hồ cùng Hạc Tử Minh và các hậu bối tiếp tục tiến vào, còn Mạnh Thiên Chính dẫn theo Thạch Hạo, Thập Quan Vương, Tào Vũ Sinh và Thích Cố. Thạch Hạo tạm giao Đại La Kiếm Thai cho Đại trưởng lão để tăng khả năng công thủ. Một đợt huyết vũ khác chuyển vào Thiết Huyết Chiến Kỳ, khiến chiến kỳ trở nên sáng ngời và được Mạnh Thiên Chính nghi là đã hấp thu Tiên Vương huyết. Luyện Tiên Hồ sau đó mở rộng khe hỗn độn do Lạc Ma từng tạo, làm khí tức cổ xưa tràn ra và để lộ một ấu cầm được nhận là Chân Hoàng. Ngay sau đó, lượng lớn tiên huyết đỏ tươi tiếp tục chảy khỏi Cổ Giới, gợi lên dấu vết của một biến cố đẫm máu thời cổ."},{"chuong":1336,"tieuDe":"Tiên Huyết","tomTat":"Khe nứt trên cự bi màu đen nối thông với cổ giới phong ấn, khiến Tiên huyết chưa luyện hóa mang sát lực khủng khiếp tràn ra. Dị vực thúc Luyện Tiên Hồ tiến lên, trong khi Mạnh Thiên Chính dùng Đại La Kiếm Thai và Thiết Huyết Chiến Kỳ dẫn đoàn Cửu Thiên tranh quyền vào cổ giới. Phượng Hoàng chưa thành niên trấn giữ vùng biên phun Bất tử Thần Diễm và ngâm thần chú, đánh thức chiến ý trong máu để tạo thành nhiều huyết linh. Luyện Tiên Hồ mở vòng xoáy thu luyện chân huyết nhưng bị quy tắc đại vũ trụ áp chế, còn Thiết Huyết Chiến Kỳ hấp thu được một phần máu và bắt đầu tự tu bổ. Các huyết linh nhặt Tử kim Tiên trượng, Hoàng kim chuy cùng những Tiên khí tàn khuyết khác để công kích, khiến vòng bảo hộ của Dị vực liên tục chấn động. Một vương giả trẻ tuổi bị chấn ra ngoài rồi chết bởi một giọt Tiên huyết, còn một lão giả cứu viện bị đạo âm nhiếp loạn và bị huyết linh xé đôi. Trước sát lực tại vùng biên, cả hai đoàn đều bị chặn ngoài cửa và chưa thể tiến vào cổ giới."},{"chuong":1337,"tieuDe":"Chân Tướng Hé Lộ","tomTat":"Những sinh linh do Tiên huyết ngưng tụ đồng loạt tan rã khi ấu cầm Phượng Hoàng kiệt sức, còn Mạnh Thiên Chính nhận ra nó chính là Đọa Lạc Huyết Hoàng đã bị chiến huyết ô nhiễm từ trong trứng. Đọa Lạc Huyết Hoàng chạy sâu vào cổ giới, khiến phe Dị vực mang Luyện Tiên Hồ truy đuổi trong khi Mạnh Thiên Chính dẫn Thạch Hạo và những người đồng hành theo sau. Sau khi từ bỏ việc khai quật các mộ tiên có uy thế đáng sợ, hai phe đi qua vùng núi trù phú rồi tiến vào một chiến trường khô cằn từng bị pháp tắc Tiên đạo quét qua. Tại đây, họ phát hiện vô số tinh thể bị một sinh linh khổng lồ kéo khỏi vũ trụ, cùng máu ngũ sắc của Lạc Ma, máu người bảo vệ và hỗn độn huyết của một đối thủ cổ xưa. Độc Cô Vân cảm ứng được huyết dịch của tộc nhân, xác nhận dòng máu người bảo vệ đồng thời mang thần tính và ma tính, đồng thời biết người để lại máu đến từ ban đầu nhất nơi chứ không thuộc thế giới hiện tại. Cuối cùng, đoàn người tìm thấy một tấm bia ghi lời của kẻ bị lựa chọn ra tay và biết mình không thể trở về, qua đó chạm đến đầu mối trực tiếp về chân tướng của trận chiến cổ xưa."},{"chuong":1338,"tieuDe":"Giải Thích Bí Văn","tomTat":"Đoàn người của Mạnh Thiên Chính tiếp tục giải đọc tấm bia cổ và biết rằng người khắc bia là một vô thượng cường giả mang hỗn độn huyết, từng đối đầu Lạc Ma cổ tổ. Bi văn kể về con đường trở về đã bị cắt đứt, các tiên hiền đều chôn xương nơi Man Hoang và dự báo một ngày đại loạn sẽ lật đổ chư thiên. Phần dưới tấm bia dùng loại văn tự cổ tỏa hỗn độn khí mà cả hai phe đều không thể nhận biết. Khi nhân giới và Dị vực tranh đoạt tấm bia, Thiết Huyết Chiến Kỳ va chạm với Luyện Tiên Hồ, còn tấm bia bất ngờ tan biến hoàn toàn. Độc Cô Vân sau đó tiết lộ tổ tiên mình có thể đến từ cùng nơi với người khắc bi văn. Tiến sâu thêm vào chiến trường, mọi người phát hiện sáu bảy thi thể Bất Hủ giả của Dị vực đã bị nuốt sạch tinh khí thần nên không ai dám chạm tới. Sau khi vượt qua vùng đất đỏ sậm rộng lớn, đoàn người đến Tiên cung cổ còn lưu chuyển khí tức Tiên Đạo và nhìn thấy một bộ xương trắng đang gảy đàn cùng Phượng Hoàng đỏ thắm chưa thành niên."},{"chuong":1339,"tieuDe":"Tiên Biến","tomTat":"Trong cổ giới, một Phượng Hoàng vị thành niên mang sát khí xuất hiện bên cạnh bộ xương trắng đang gảy đàn, còn tiếng đàn khiến nhóm người trẻ rơi vào ảo giác thấy tuyệt đại tiên tử tái sinh. Mạnh Thiên Chính dùng đạo âm đánh thức mọi người và nhận ra cây đàn là Phượng ngô Tiên cầm, pháp khí nổi danh của Cửu Thiên Thập Địa được luyện từ lõi thần thụ Phượng Hoàng nhưng nay đã rách nát. Sau khi Huyết Hoàng giao lưu với bộ xương, dây đàn cùng âm phù phát động công kích không phân biệt, buộc Luyện Tiên Hồ, Thiết Huyết Chiến Kỳ và Đại La Kiếm Thai cùng tham gia đối kháng. Một thi thể Phượng Hoàng trưởng thành bay khỏi cổ kiến trúc, rồi Tiên Đạo tàn trận hiện lên và cuốn cả hai phe vào cảnh cổ chiến trường đầy di hài Chí Cường giả. Dị vực dùng Luyện Tiên Hồ phá trận, còn Mạnh Thiên Chính phối hợp Thiết Huyết Chiến Kỳ với Đại La Kiếm Thai mở đường đưa nhóm Cửu Thiên thoát ra. Khi quần thể kiến trúc sụp đổ, tế đàn trung tâm lộ diện với một Tiên mộc quan tài vẫn còn sinh cơ, đang được tinh huyết thần bí và huyết tinh Bất Hủ giả của Dị vực cung dưỡng. Tiếng đàn sau đó chuyển thành âm điệu bi thương như chiêu hồn, dẫn sáu thi thể Bất Hủ giả cùng các thi thể từ mộ tiên tới gần, khiến hai phe rơi vào nguy cơ bị Tiên thi vây giết."},{"chuong":1340,"tieuDe":"Nhiễu Loạn Vạn Cổ Mộng","tomTat":"Tiếng đàn của nữ tử xương trắng triệu gọi hàng loạt Tiên thi cùng sáu Bất Hủ thi hài, khiến đoàn Cửu Thiên và Dị vực cùng rơi vào vòng vây chết chóc. Mạnh Thiên Chính dùng Tiên Vương quấn vải liệm, còn các lão giả Dị vực thúc giục Luyện Tiên Hồ tìm đường vượt hư không, nhưng cổ đại trận thức tỉnh và khóa chặt mọi lối thoát. Hai phe nhận ra tiếng đàn là nguồn điều khiển quần thi nên đồng thời tấn công nữ tử xương trắng, song Phượng ngô Tiên cầm và thi hài Bất Tử Phượng Hoàng trưởng thành đứng ra bảo vệ nàng. Các lão giả Dị vực tiến hành nghi thức gần như tế tự để đánh thức Luyện Tiên Hồ, khiến pháp khí cắt đứt tiếng đàn, đánh văng thi hài Phượng Hoàng và làm nữ tử xương trắng tan thành một đống xương, dù nàng nhanh chóng tự hợp lại. Cương phong từ pháp khí đồng thời làm nắp Tiên mộc quan tài trên tế đàn trở nên trong suốt, để lộ một nữ tử tuyết y có dung mạo giống nữ tử xương trắng nhưng thân thể dường như chỉ là lớp da rỗng. Khi nữ tử trong quan tài mở mắt, trường vực của nàng khóa cả Luyện Tiên Hồ lẫn Tiên Vương quấn vải liệm rồi cưỡng ép kéo hai phe trở lại. Nàng cất tiếng chất vấn kẻ đã quấy nhiễu giấc mộng vạn cổ và phá vỡ sự yên tĩnh của mình."},{"chuong":1341,"tieuDe":"Tự Thành Cấm Địa","tomTat":"Nữ tử trong Tiên mộc quan tài hoàn toàn thức tỉnh dưới hình thái được nhận định là quỷ thành tiên, trong khi quan tài chỉ còn lại một tấm da người hoàn mỹ. Nhân mã Dị vực điên cuồng thôi thúc Luyện Tiên Hồ, nhưng nàng chỉ dùng một ngón tay đã hóa giải uy lực của pháp khí này. Mạnh Thiên Chính vận dụng Thiết Huyết Chiến Kỳ làm hiện Tiên huyết của các Tiên Vương, khiến nàng thoáng nhớ lại quá khứ nhưng vẫn quả quyết chặt đứt mọi liên hệ. Nữ tử đẩy Luyện Tiên Hồ và Thiết Huyết Chiến Kỳ vào bàn cờ trận pháp, sau đó tuyên bố cổ giới tự thành cấm địa và đánh văng cả hai phe ra ngoài. Trước khi dùng cự bi đen phong ấn cổ giới lần thứ hai, nàng ném cho phía Cửu Thiên một nhánh hương khắc hai chữ Tiên văn cổ Giới diệt. Dị vực định tranh đoạt vật này nhưng phải nhịn xuống trước Đại La kiếm thai, Thiết Huyết Chiến Kỳ, Thế Giới Thụ cây non và sừng Thiên Giác Nghĩ. Trở lại Đại Xích Thiên biên cương, Độc Cô Vân suy đoán nữ tử có thể là cường giả từng quyết chiến với Lạc Ma, còn Thạch Hạo bắt đầu suy ngẫm về nguồn gốc của những vùng cấm trong Cửu Thiên Thập Địa."},{"chuong":1342,"tieuDe":"Tàn Khốc Thời Đại Đã Đến","tomTat":"Tại Đại Xích Thiên biên cương, hai phe Cửu Thiên và dị vực đứng nhìn nhau qua vực sâu hắc ám trong khi Luyện Tiên Hồ xé mở Càn Khôn trở lại. Lời đe dọa từ phía dị vực khiến Tào Vũ Sinh tức giận đáp trả, còn Thạch Hạo công khai tuyên bố sẽ chém chư vương rồi giết Đế tộc. Hạc Tử Minh khiêu chiến Thạch Hạo, đồng thời chư vương dị vực tiết lộ rằng các Đế tộc An Lan và Du Đà vẫn còn những tuổi trẻ Đế Giả chưa xuất thế. Khi dị vực rút lui, những bàn tay khổng lồ từng chống giữ vực sâu cũng rời đi, khiến thông đạo chậm rãi khép kín. Mạnh Thiên Chính đưa đoàn người xuyên qua Cửu Thiên trở về Vô Lượng Thiên rồi giao chiến thuyền cho Thạch Hạo tự điều khiển. Tại Thiên Thần Thư Viện, Thạch Hạo cảnh báo rằng một thời đại tàn khốc đã đến. Người của Vương Hi gia tộc bất ngờ xuất hiện, chất vấn những người trở về và gọi họ là đào binh, khiến Thạch Hạo nhận ra một tín hiệu nguy hiểm ở hậu phương."},{"chuong":1343,"tieuDe":"Phát Điên","tomTat":"Một nhóm cường giả Vương gia do Vương Thiên Minh cầm đầu kéo tới Thiên Thần Thư Viện, tự đặt mình vào vị trí chủ sự và yêu cầu Thạch Hạo chịu thẩm vấn. Thạch Hạo cùng Tào Vũ Sinh công khai phản bác, chỉ ra rằng người Vương gia không xuất hiện tại biên cương nhưng lại áp chế người mình ở hậu phương. Vương Thiên Minh vu cáo họ tự ý rời chiến trường và hạ lệnh bắt giữ, trong khi trưởng lão lưu thủ của thư viện bị hai lão giả Vương gia kiềm chế. Thạch Hạo thuật lại thương vong tại Đại Xích Thiên cùng chiến tích mười trận thắng liên tiếp, song Vương Thiên Minh vẫn cố tình phủ nhận. Mục đích thật của Vương gia là bắt hắn để dò xét thần thức, tìm phần kinh văn lấy được tại bãi đá Bắc Hải mà Vương Trường Sinh suy diễn có thể là Bất Diệt Kinh. Khi Vương Thiên Minh phớt lờ cảnh cáo và tiến lên trấn áp, một chiến mâu màu đen bất ngờ lao lên từ dưới đất, xuyên thủng rồi nhấc bổng ông ta. Tiểu Thiên Giác Nghĩ sau đó dẫn các cổ chiến giả mặc giáp đen xuất hiện từ lòng đất và tuyên bố nơi đây là địa bàn của mình."},{"chuong":1344,"tieuDe":"Đằng Đằng Sát Khí","tomTat":"Thiên Giác Nghĩ bí mật tới Tiên phủ điều năm chiến binh khôi lỗi, khiến viện binh bất ngờ phá đất xuất hiện tại Thiên Thần Thư Viện và khống chế Vương Thiên Minh. Theo lệnh Thạch Hạo, thủ lĩnh khôi lỗi kích phát lửa đen trên chiến mâu, thiêu Vương Thiên Minh thành than và tiêu diệt cả nguyên thần. Thạch Hạo cùng Tào Vũ Sinh công khai vạch trần việc Vương gia lấy danh nghĩa dò xét để bắt người có công từ chiến trường và ép hỏi Bất Diệt Kinh. Khi đoàn Vương gia tiếp tục uy hiếp, Thạch Hạo đánh chết người trẻ tuổi và dùng Đại La kiếm thai đâm thủng tay người trung niên định bắt mình làm con tin. Năm chiến binh khôi lỗi sau đó triển khai chiến trận, phá nát bảo cụ hộ thân rồi tiêu diệt hai nguyên lão cùng toàn bộ những người Vương gia còn lại. Sau cuộc sát phạt, Thạch Hạo quyết định nhổ bỏ các cứ điểm Vương gia tại Vô Lượng Thiên, ưu tiên khu vực gần Thiên Thần Thư Viện. Trước sự lo ngại của trưởng lão thư viện về Cửu Long và Vương Trường Sinh, Thạch Hạo bí mật tiết lộ rằng Đại trưởng lão đã trở về và vẫn chưa rời đi."},{"chuong":1345,"tieuDe":"Kích Vương Gia","tomTat":"Sau khi tiêu diệt nhóm người Vương gia trước đó, Thạch Hạo cùng Tào Vũ Sinh, Trường Cung Diễn và các đồng bạn hỏi vị trưởng lão lưu thủ về vị trí những cứ điểm đang giám thị Thiên Thần Thư Viện. Họ dùng chiến thuyền đánh thẳng vào hạ viện gần nhất, phá xuyên đại trận, trận đài, cửa lớn và bắt sống người trung niên cầm đầu. Qua việc dò xét biển ý thức tù binh, trưởng lão phát hiện Vương Trường Sinh đã suy tính ra Bất Diệt Kinh thuộc về Thạch Hạo, qua đó làm rõ nguyên nhân Vương gia nhắm tới hắn. Thạch Hạo bác bỏ lời thỏa hiệp, chém đầu và diệt nguyên thần người cầm đầu rồi tiếp tục san bằng tổng cộng bốn cứ điểm Vương gia trong cùng ngày. Để đáp trả, Vương Chân dẫn hàng trăm chiến xa cùng hàng nghìn tinh nhuệ áp sát Thiên Thần Thư Viện và gọi Hoang ra hỏi tội. Thạch Hạo đứng trên núi cao, công khai chất vấn vì sao Vương gia không tới Biên Hoang chống dị vực mà lại đem lực lượng tinh nhuệ vây nhốt thư viện."},{"chuong":1346,"tieuDe":"Vương Bài","tomTat":"Vương Chân dẫn hàng trăm chiến xa cùng mấy nghìn tinh nhuệ Vương gia vây Thiên Thần Thư Viện, lấy danh nghĩa đòi công đạo cho con cháu đã chết để ép Thạch Hạo đến linh đường. Thạch Hạo bác bỏ yêu cầu, còn Thiên Giác Nghĩ và Tào Vũ Sinh chỉ ra rằng Vương gia mới là bên chủ động gây chuyện và có thể đang nhắm tới kinh văn trên người hắn. Vương Cát chế giễu sự suy tàn của bộ tộc Thiên Giác Nghĩ, khiến con kiến nhỏ nổi giận và làm mâu thuẫn hoàn toàn bùng phát. Khi Vương Cát ra lệnh tiến công, Thạch Hạo thỉnh năm binh sĩ con rối mặc giáp đen xuất chiến. Mấy nghìn tinh nhuệ Vương gia triển khai tuyệt thế chiến trận, nhưng năm binh sĩ vẫn quét ngang đội hình, phá hủy chiến xa và giết hàng loạt quân sĩ. Một binh sĩ dùng chiến mâu xuyên thủng Vương Cát rồi nhấc ông ta lên giữa không trung. Chứng kiến chiến lực ấy, Thạch Hạo vừa kinh ngạc vừa đau xót vì những chiến sĩ từng chống Dị vực tại Biên Hoang nay phải bất đắc dĩ xuống tay với người Cửu Thiên."},{"chuong":1347,"tieuDe":"Diệt Trận","tomTat":"Vương Chân xin tha cho Vương Cát nhưng Thạch Hạo kiên quyết ra lệnh xử tử, khiến thủ lĩnh lão binh dùng chiến mâu đánh Vương Cát tan thành mưa máu. Vương Chân lập tức điều động mấy nghìn quân Vương gia cùng hàng trăm Thanh Đồng trận đài, dựng cổ lão sát trận để vây giết năm lão binh. Đại trận bảo hộ binh sĩ và liên tục triệu hoán tiền sử cự hung, còn những mảnh Tiên Đạo pháp chỉ được dùng để tăng cường phòng ngự và công kích. Thủ lĩnh lão binh tế Tiên gia chiến kỳ, thiêu hủy pháp chỉ, đánh nát hàng chục trận đài và phá vỡ toàn bộ chiến trận. Năm lão binh xông vào đội hình quân Vương gia, nhanh chóng áp sát Vương Chân và nghiền nát mảnh pháp chỉ cuối cùng bằng phù văn chúc phúc của Thiên Giác Nghĩ. Họ đồng thời đâm xuyên thân thể, phong bế Nguyên Thần rồi chấn Vương Chân thành thịt nát, bất chấp hắn viện dẫn Cửu Long của Vương gia để cầu sống. Sau trận, các lão binh công khai tuyên bố chờ chín con rồng tới."},{"chuong":1348,"tieuDe":"Cửu Long Xuất Thế","tomTat":"Sau cái chết của Vương Chân, quân trận Vương gia mất người chỉ huy và bị năm lão binh dùng cờ Tiên chiến nghiền chết hơn năm trăm người, rồi trấn áp khoảng ba nghìn binh mã còn sống. Thạch Hạo buộc số tù binh lựa chọn giữa cái chết và thần phục, đồng thời chém đầu, phá hủy Nguyên Thần của một chiến tướng công khai chống lệnh. Hắn lên án Vương gia án binh bất động khi các tộc khác đã tới Biên Hoang, công khai nghi ngờ gia tộc này tư thông dị vực và yêu cầu họ điều quân ra tiền tuyến để chứng minh sự trong sạch. Tin tức nhanh chóng lan khắp Cửu Thiên, khiến các đại tộc và những lão quái vật lưu thủ âm thầm bàn bạc về thái độ của Vương gia. Không lâu sau, Cửu Long xuất thế và điều động tọa giá khổng lồ của Vương Trường Sinh tiến thẳng tới Thiên Thần Thư Viện. Vương Nhị đứng ở đầu chiến thuyền, triển khai Pháp tướng cao hàng vạn trượng và tuyên bố sẽ hủy đạo trường để báo thù. Cuối cùng, ông lấy Trường Sinh chiến phủ, Tiên khí trấn tộc của Vương gia, khiến thiên địa rung chuyển và chuẩn bị đánh xuống thư viện."},{"chuong":1349,"tieuDe":"Trường Sinh Chiến Kích","tomTat":"Vương Nhị mang Trường Sinh chiến kích đến tấn công Thiên Thần Thư Viện để báo thù cho con trai, khiến thiên địa và tinh tú rung chuyển trước uy thế của Tiên Đạo binh khí. Các trưởng lão kích hoạt một góc Tiên Đạo tàn trận, nhưng màn sáng và thuẫn bài phòng hộ lần lượt bị chiến kích phá vỡ, khiến năng lượng tích lũy gần như cạn kiệt. Vương Nhị tiếp tục phát động đòn tuyệt diệt và tuyên bố sẽ giữ Thạch Hạo sống để hành hạ. Thạch Hạo trao Đại La kiếm thai cho thủ lĩnh lão binh nghênh chiến, làm thanh kiếm phát huyết quang và hiện bóng người như đang cử hà phi tiên. Vương Đại xuất hiện trên chiến thuyền, tế Thủy Tổ pháp chỉ để cầm cố kiếm thai và phối hợp với chiến kích mưu đoạt bảo vật. Trước thế công ấy, thủ lĩnh lão binh gọi Nguyên Mẫu Đỉnh từ lòng đất lên, tạo vòng xoáy khổng lồ nhằm thu lấy Trường Sinh chiến kích, khiến Vương Nhị kinh hãi."},{"chuong":1350,"tieuDe":"Phục Long","tomTat":"Vương Nhị cố giữ Trường Sinh chiến kích nhưng lực hút từ Nguyên Mẫu Đỉnh dưới lòng đất Thiên Thần Thư Viện vẫn kéo Tiên khí trở lại, tạo cơ hội cho các lão binh tranh đoạt. Bí mật về chiếc đỉnh từng thuộc Thiên Giác Nghĩ được hé lộ: chân thân của nó còn bị phong ấn, song uy thế đã đủ nuốt thần lực và bảo vệ toàn bộ thư viện. Vương Đại, Vương Nhị, Vương Tam cùng hai người khác hợp thành đội hình năm con rồng, dùng pháp chỉ và chiến kích đánh xa nhưng mọi công kích đều bị vòng xoáy dưới lòng đất hóa giải. Năm lão binh chủ động xuất trận, còn Mạnh Thiên Chính bất ngờ xuất hiện phía sau chiến thuyền để khép kín vòng vây. Ông dùng Thiết Huyết Chiến Kỳ trấn áp pháp chỉ của thủy tổ Vương gia rồi ném nó xuống cho Nguyên Mẫu Đỉnh nuốt giữ. Trong cuộc giao tranh sau đó, Vương Nhị bị Đại La kiếm thai đánh gãy một tay và mất Trường Sinh chiến kích, bốn người còn lại cũng chịu thương tích nặng. Ý thức chiến đấu thời Tiên cổ của năm lão binh thức tỉnh, giúp họ bắt sống toàn bộ năm con rồng Vương gia."},{"chuong":1351,"tieuDe":"Tù Nhân","tomTat":"Năm Long Vương gia gồm Vương Đại, Vương Nhị, Vương Tam, Vương Tứ và Vương Ngũ bị các lão binh Tiên cổ đánh bại, trọng thương rồi giam giữ tại Thiên Thần Thư Viện. Vương Đại định tấn công Tiểu Thiên Giác Nghĩ nhưng bị chiến mâu xuyên thân đóng đinh xuống đất, còn Vương Nhị tập kích Thạch Hạo rồi bị đại kích chém thân thể thành hai đoạn. Vương Ngũ triệu hoán Thủy tổ pháp chỉ nhưng bảo vật bị Nguyên Mẫu Đỉnh áp chế, trong khi Trường Sinh chiến kích do Vương Nhị gọi về cũng bị Mạnh Thiên Chính dùng Thiết Huyết Chiến Kỳ trấn áp. Trước những lời đe dọa dựa vào Vương Trường Sinh và Vương Cửu, Mạnh Thiên Chính tuyên bố chừng nào còn sống sẽ không cho Vương gia gây loạn, đồng thời đặt kỳ vọng vào sự quật khởi của Thạch Hạo. Thạch Hạo hiểu được ánh mắt ấy và quyết tâm giành lấy thực lực cái thế để chống Dị vực, áp chế Vương gia và bảo vệ Thiên Thần Thư Viện. Vương Tứ định đánh Tào Vũ Sinh nên bị một lão binh chém đầu nhưng chưa chết. Theo đề nghị của Tào Vũ Sinh và Tiểu Thiên Giác Nghĩ, năm lão binh bạt tai năm Long trước mặt tu sĩ các tộc, khiến uy danh lâu đời của Vương gia chịu nhục nặng nề."},{"chuong":1352,"tieuDe":"Đày Đi Biên Hoang","tomTat":"Năm lão binh Tiên cổ hoàn toàn áp đảo năm con rồng Vương gia, đánh họ trọng thương và khiến Vương Ngũ bị lìa đầu trước khi Mạnh Thiên Chính ra lệnh dừng tay. Đại trưởng lão không giết năm người mà quyết định đưa họ tới Biên Hoang giết địch, bất chấp việc họ liên tục chống lệnh và đòi gia tộc can thiệp. Kim thái quân đi cổ chiến xa từ Thanh Vi Thiên tới Thiên Thần Thư Viện để cầu tình, dựa vào quan hệ thông gia giữa Kim gia và Vương gia, nhưng Mạnh Thiên Chính kiên quyết từ chối. Ông tiết lộ hậu nhân của mình cũng đang chiến đấu tại Biên Hoang và chấp nhận để họ chết trận, khiến những người chứng kiến kính phục. Nhiều nhân vật cổ xưa thuộc các Trường Sinh thế gia cùng xuất hiện để ủng hộ quyết định này, buộc Kim thái quân phải nhượng bộ. Cuối cùng, Vương Trường Sinh mở cánh cửa không gian đưa binh mã tới, chấp nhận cho năm con rồng ra Biên Hoang lập công và cam kết điều thêm mười vạn tinh binh."},{"chuong":1353,"tieuDe":"Mục Tiêu Biên Hoang","tomTat":"Vương Trường Sinh mở không gian chi môn, điều mười vạn tinh binh dòng chính Vương gia tới tiếp viện biên hoang và giao toàn quân cho năm người con chỉ huy. Ông không đón các con trở về mà buộc họ tới tiền tuyến giết địch, lập công chuộc tội. Kim thái quân tháo cấm chế cho năm con rồng, giúp họ nối lại thân thể và phục hồi hoàn toàn, nhưng họ vẫn lạnh lùng nhìn nhóm Thạch Hạo. Vương Trường Sinh sau đó hiện thân tại Thiên Thần thư viện với diện mạo thiếu niên và thực lực được xác nhận đạt nửa bước Tiên Nhân. Mạnh Thiên Chính tiết lộ phần kinh văn trong Nguyên Thần Thạch Hạo đã được chín đạo cấm chế bảo vệ, đồng thời hứa cho Vương gia xem nếu thế lực này lập đại công cho Cửu Thiên Thập Địa. Mười vạn quân được Mạnh Thiên Chính và một cự đầu Trường Sinh thế gia dẫn tới biên hoang, còn các cự đầu khác rời đi hoặc lưu thủ hậu phương. Cuối cùng, Thạch Hạo cùng thế hệ trẻ được hiệu triệu tới biên hoang trải qua máu lửa, tìm cơ duyên và con đường tiến tới Chí Tôn hoặc chiến tiên."},{"chuong":1354,"tieuDe":"Thiên Tài Tập Hợp","tomTat":"Các kỳ tài hàng đầu khắp Cửu Thiên Thập Địa nhận được lời triệu hoán của những kỳ nhân chung thuộc Tiên Viện, Thánh Viện và Thiên Thần Thư Viện. Tam viện chính thức hợp nhất, mở đạo trường tại một đoạn Tiên cổ tổ mạch ở Vô Lượng Thiên và dự định dành một năm truyền kinh, giảng giải về dị vực cùng rèn luyện thực chiến trước khi tiến ra Biên Hoang. Thạch Hạo đến nơi, gặp lại Thanh Y, Ma Nữ, Thái Âm Ngọc Thỏ cùng nhiều thiên tài, đồng thời chú ý đến Kim Triển với Tiên vụ và tiên khí nồng đậm quanh thân. Trong buổi tụ hội, mọi người nhắc lại chiến tích của Thạch Hạo tại Đại Xích Thiên và những tổn thất như cái chết của Tử Nhật Thiên Quân, Lữ Hồng. Các lão giả sau đó hé lộ một Đế Tộc dị vực cổ xưa hơn An Lan và Du Đà, sở hữu tổ thuật miễn dịch vạn pháp đã được nghiên cứu qua nhiều kỷ nguyên. Thạch Hạo liên hệ năng lực ấy với dị lực miễn dịch pháp lực của bản thân và quyết tâm giao chiến với Đế Tộc này để hoàn thiện con đường của mình. Chương kết thúc khi một người trẻ tuổi đặt câu hỏi nghiêm trọng về cách Cửu Thiên Thập Địa chống lại Bất Hủ dị vực trong hoàn cảnh đã lâu không còn Chân Tiên."},{"chuong":1355,"tieuDe":"Cựu Địa Mật Thổ","tomTat":"Trước nỗi bi quan của lớp tu sĩ trẻ, dị nhân ông lão thừa nhận Dị vực cực kỳ hùng mạnh nhưng khẳng định biên hoang vẫn có những lá bài tẩy chưa lộ. Ông tiết lộ bên ngoài Đế Thành còn có một cựu thành nằm giữa hư vô, hỗn độn và ma thổ nhuốm máu, đủ sức trấn áp khu vực giữa hai giới và khiến cấp bất hủ của Dị vực kiêng kỵ. Thạch Hạo liên hệ cựu thành này với cô thành từng hiện ra trên tế đàn của cổ thuyền màu đen, nơi biên hoang thất vương cùng người già và trẻ nhỏ lấy máu và sinh mạng chống giữ. Hắn khẳng định tội huyết là vinh quang của tổ tiên chứ không phải tội lỗi. Dị nhân ông lão tiếp tục kể về Thiên Uyên cùng rừng bia ngộ đạo, cựu thổ tiên gia, dãy núi thần dược, rừng Thiên thú, Táng vực và những hiểm địa từng khiến quân Dị vực mất tích. Các ông lão cảnh báo rằng một trăm thiên tài tiến vào những mật thổ ấy có thể chỉ còn vài người sống sót, nên người muốn đến biên hoang phải sẵn sàng hi sinh. Sau khi được Thanh Y, Tào Vũ Sinh và những người quen hỏi thăm, Thạch Hạo vẫn quyết định chuẩn bị đầy đủ rồi lên đường tới biên hoang."},{"chuong":1356,"tieuDe":"Đối Lập","tomTat":"Thế hệ trẻ Cửu Thiên tiến vào Tiên thổ, tranh nhau mười ngọn núi nằm trên đoạn tổ mạch Tiên cổ để làm đạo trường tu luyện. Tiểu Thiên Vương chiếm một ngọn núi trước tiên, còn Thạch Hạo nhanh chóng giành được một trong bốn ngọn núi tốt nhất và gọi những người quen cùng lên núi. Uy danh từ chiến tích mười trận toàn thắng tại Đại Xích Thiên khiến những người định tranh đoạt với hắn đều lặng lẽ rút lui. Kim Triển dẫn Vương Hi cùng các đệ tử Thánh Viện tới đối diện Thạch Hạo, khiến hư không nổ tung vì khí thế va chạm, nhưng một lão quái vật đã ngăn hai người giao chiến và khuyên họ so tài giết địch tại Biên Hoang. Sau cuộc tranh luận giữa những người ủng hộ hai bên, các thiên kiêu còn lại lần lượt tìm được đạo trường riêng. Thạch Hạo ngồi xuống tu luyện và lấy Ngọc thạch thư thu được từ quan tài cổ ra xem, bởi lúc này hắn đã đạt Hư Đạo cảnh. Thần niệm vừa tiến vào kinh thư đã dẫn phát dị tượng Chân Long, Bất Tử Hoàng Điểu, Phi Tiên ánh sáng cùng khí tượng Tiên Đạo, khiến mọi người kinh ngạc nhận ra đây là một bộ Tiên kinh."},{"chuong":1357,"tieuDe":"Tiên Kinh","tomTat":"Sau khi đạt Hư Đạo cảnh, Thạch Hạo tự mở được Ngọc thạch thư từng bị sức mạnh lớn phong kín và phát hiện bên trong là một bộ Tiên kinh gần như tuyệt tích. Kinh thư phát sáng, hiện ra dị tượng Chân Long, Bất Tử điểu và mưa sáng Phi Tiên, khiến các thiên kiêu của ba đại thư viện cùng nhiều Trường Sinh thế gia sinh lòng mơ ước nhưng không ai dám trực tiếp cướp đoạt. Thạch Hạo công khai đề nghị Vương gia dùng Bình Loạn Quyết trao đổi, rồi yêu cầu Kim gia mang trấn tộc cổ kinh rèn luyện gân cốt khi Kim Triển ngỏ ý đổi kinh. Qua nội dung Tiên kinh, hắn lần đầu hiểu đạo chủng, mồi lửa, Ma chủng và tiên chủng đều quy về nền tảng “chủng” của cổ pháp. Hắn cũng nhận ra ba đạo tiên khí do mình cưỡng ép ngưng tụ tuy đã hóa thành đại đạo chi hoa nhưng vẫn giống bèo không rễ. Khi vận chuyển kinh văn để điều chỉnh con đường lấy thân làm chủng, tiên khí bắt đầu tuần hoàn gột rửa từng tấc cơ thể, xương cốt cộng hưởng Tiên âm và mở đầu một lần biến hóa gần như thoát thai hoán cốt."},{"chuong":1358,"tieuDe":"Một Năm Vội Vã","tomTat":"Thạch Hạo chuyên tâm lĩnh hội Tiên kinh lấy “Chủng” làm cội nguồn, khiến ba đạo tiên khí phân giải thành hi quang và cắm rễ trong từng tấc máu thịt. Lần ôn dưỡng đầu tiên đồng thời cưỡng ép chỉnh sửa đạo cốt, loại bỏ phần xương không phù hợp và đưa hắn tiến gần trạng thái Tiên cơ đạo cốt. Trong khi đó, Tiểu Thiên Vương, Kim Triển, Đại Tu Đà cùng nhiều chí tôn trẻ tuổi vẫn kiên định tu luyện con đường riêng trên Tiên cổ tổ mạch. Sau ba ngày, Thạch Hạo tỉnh lại và chia sẻ kinh văn với Thanh Y, Trường Cung Diễn, Tào Vũ Sinh cùng những người quen để giúp họ tăng khả năng sống sót trong thời đại hắc ám. Qua lời giải đáp của các tiền bối, mọi người biết Vô Chung Tiên Vương và Lục Đạo Luân Hồi Tiên Vương đều đã chết trận, trong đó đòn cuối nhằm vào Lục Đạo đến từ cao thủ tuyệt thế của Thần Cô tộc. Các ông lão còn hé lộ Thần Cô tộc vốn là một nhánh Cô tộc thuộc Thập Hung phản bội sang dị vực, sau đó dị biến và trở nên mạnh hơn. Gần một năm trôi qua, nhóm tu sĩ trẻ tuổi vừa tu luyện vừa tìm hiểu Biên Hoang và kẻ địch dị vực. Khi ngày xuất phát tới gần, Thiên Giác Nghĩ tuyên bố quyết tâm báo thù, còn đông đảo thiên tài khác cũng sẵn sàng lên đường bất chấp hiểm nguy và tử vong."},{"chuong":1359,"tieuDe":"Rời Đi","tomTat":"Trước khi kỳ hạn một năm kết thúc, Thạch Hạo dành trọn một tháng tìm hiểu Tiên kinh, khiến tiên khí phân giải và cắm rễ khắp thân thể, đồng thời hoàn thành một lần thay máu để củng cố căn cơ. Khi ngày khởi hành tới, hơn một trăm năm mươi thiên tài trẻ tuổi lựa chọn tới biên hoang, nhưng các lão nhân chỉ tuyển một trăm người cho đợt đầu nhằm tránh để toàn bộ tinh anh Cửu Thiên cùng gặp đại nạn. Tế đàn màu đen được kích hoạt, đưa đoàn người rời Vô Lượng Thiên và tiến vào khu không người ở biên hoang. Trên đường, họ chạm mặt thần bì còn chấp niệm của một chí cường giả và một đầm lầy bị máu của sinh linh nửa bước Chân Tiên nhuộm đỏ, qua đó trực tiếp cảm nhận mức độ nguy hiểm của chiến địa. Các lão nhân dẫn đoàn đi theo cổ lộ an toàn cho tới khi Đế Thành khổng lồ hiện ra như một vùng vũ trụ cổ. Đứng trước thành trì trấn thủ biên hoang, Thạch Hạo ngoái nhìn về quê cũ, nhớ cha mẹ, người Thạch thôn và Hỏa Linh Nhi, đồng thời lo rằng chuyến đi này có thể mở đầu cho cuộc ly biệt kéo dài nửa đời."},{"chuong":1360,"tieuDe":"Biên Hoang Đế Quan","tomTat":"Đoàn tu sĩ trẻ tuổi đến trước Đế Thành, hùng quan khổng lồ được xây trên đầu mối không gian trọng yếu để ngăn dị vực tiến quân vào Cửu Thiên Thập Địa. Các kỳ nhân lần lượt ghép bạch cốt tiểu tế đàn và đàn tròn từ xương vàng, đưa hơn một trăm người vượt qua ngoại thành rồi tiến vào nội thành. Trên đường đi, đoàn người chứng kiến những tu sĩ thủ quan tọa quan lâu năm, Thôn Thiên thú được nuôi bằng ngôi sao và một đại thần tiễn thủ có khả năng bắn vỡ tinh thể ở tinh vực khác. Họ còn gặp đội đại kỵ sĩ mang thi thể cùng tù binh dị vực trở về, nhưng ngay sau đó lại thấy hàng chục nghìn quân sĩ với một nửa số người đang khiêng quan tài, cho thấy chiến sự biên quan vô cùng khốc liệt. Càng tiến sâu, Đế Thành càng hiện ra như một đại thế giới với núi non, thác nước, linh sơn và những vùng sinh thái rộng lớn. Tại cấm địa gần trung tâm thành, Thạch Hạo bị một đoạn cọc cây khô khổng lồ tác động, nghe các truyền thuyết mâu thuẫn về cao thủ Tiên cổ và tế linh tối cao rồi thất thần nhìn nó."},{"chuong":1361,"tieuDe":"Truyền Thuyết","tomTat":"Thạch Hạo nhìn thấy một thân cây cháy đen phát ra chớp Bất Hủ và lập tức liên tưởng đến Liễu Thần, nhưng tin rằng Liễu Thần vẫn còn sống. Một lão kỳ nhân kể thân cây vốn là Tiên thụ cấp Tiên Vương, từng chín lần đánh vào dị vực rồi trở ra trong máu kẻ địch, trước khi nộ chiến lần cuối vào thời Cửu Thiên Thập Địa luân hãm. Mọi người tranh luận liệu Tiên thụ đã chết thật hay chỉ chém bỏ quá khứ, lưu Tiên thể tại đây và bắt đầu lại từ một hạt giống để chờ ngày niết bàn. Đoàn thiên kiêu sau đó đến thánh thổ, nơi tiếng chuông từ đồng điện triệu tập các đại tộc và đạo thống tới đón hậu bối. Vương Trường Hà của Vương gia đón Vương Hi, hết lời nâng cao Kim Triển và ngầm chèn ép Thạch Hạo, trong khi nhiều thiên kiêu khác cũng lần lượt được người của thế lực mình tiếp nhận. Cuối cùng chỉ còn Thạch Hạo, Thạch Nghị, Tần Hạo và Tào Vũ Sinh không có người đón; Vương Trường Hà nhân đó công khai gọi Thạch Hạo là dư nghiệt Thạch Tộc và hậu duệ Tội Huyết có căn nguyên bất chính."},{"chuong":1362,"tieuDe":"Lai Lịch Quá To Lớn","tomTat":"Tần Hạo, Thạch Hạo và Thạch Nghị phản bác việc hậu nhân Thạch Tộc bị gọi là Tội Huyết, đồng thời dùng thân phận từng bị đày của Vương Trường Hà để đáp trả. Hoàng Kim cự nhân, đại nhân vật Kim gia và Cố Minh đạo lần lượt kết tội Thạch Tộc, trong đó Cố Minh đạo còn yêu cầu Thạch Hạo bỏ họ nếu muốn được tha thứ. Diệp Khuynh Tiên bất ngờ xuất hiện để đón Thạch Hạo, bác bỏ định luận đang lưu truyền và yêu cầu những kẻ phỉ báng phải xin lỗi. Từ Tổ đàn, ba nhân vật vô địch phát thần uy khiến các đại nhân vật chống đối run rẩy và quỳ xuống. Ba thân ảnh tinh lực khổng lồ hiện lên rồi trải kim quang đại đạo tới chân nhóm Thạch Hạo, công khai biểu thị thái độ bảo vệ hậu nhân Thạch Tộc. Trước uy áp ấy, Vương Trường Hà cúi đầu nhận sai, Cố Minh đạo tự vả miệng, còn người của Kim gia, Vương gia và các bên liên quan đều phải hành đại lễ nhận tội."},{"chuong":1363,"tieuDe":"Hình Ảnh Kia Thật Đẹp","tomTat":"Tinh lực và dấu ấn đại đạo từ tổ đàn ngưng tụ thành ba Pháp tướng uy thế ngập trời, đánh ngã Cố Minh Đạo, Vương Trường Hà cùng nhiều người từng sỉ nhục Thạch Tộc và đảo ngược hoàn toàn cục diện. Thạch Hạo, Thạch Nghị, Tần Hạo và Tào Vũ Sinh được kim quang đại đạo tiếp dẫn, nhận đạo tắc cộng hưởng cùng pháp lực gột rửa. Tại điểm cuối, cả nhóm phát hiện ba cường giả không có chân thân ở đó mà chỉ là chấp niệm lưu trên ba bức khắc đá. Diệp Khuynh Tiên xác nhận họ lần lượt là tổ tiên Thạch Tộc, tổ tiên Hỏa tộc và chiến hữu của hai người, đồng thời đều thuộc Biên Hoang bảy Vương. Nàng tiết lộ đã dùng vài khối tổ cốt của cổ tổ dị vực làm tế phẩm để đánh thức chấp niệm trên khắc đá tại tổ đàn do Chân Tiên thời Tiên cổ dựng nên. Diệp Khuynh Tiên còn cố ý để phe đối địch trước hết tin rằng các cường giả cổ đại đang bảo hộ Thạch Tộc, rồi về sau biết sự thật để càng thêm nhục nhã. Không cam lòng, Cố Minh Đạo cùng Vương Trường Hà và các cao thủ vận dụng quan hệ trong Đế Thành, tìm đến một lão nhân cấp lão tổ để hỏi chân tướng. Chương kết thúc khi lão nhân tóc thưa hỏi Cố Minh Đạo có thật sự muốn biết sự thật hay không."},{"chuong":1364,"tieuDe":"Tội Huyết Tộc Nhân","tomTat":"Sinh linh già yếu tại tổ đàn tiết lộ ba cường giả từng khiến nhóm Cố Minh Đạo kinh sợ chỉ là anh linh được dẫn ra từ hình khắc đá nhờ nghi thức hiến tế. Vừa phẫn nộ vừa xấu hổ vì mắc lừa, Cố Minh Đạo và Vương Trường Hà mưu tính kết trọng tội cho Thạch Tộc Tam huynh đệ rồi tới tổ đàn cầu viện, nhưng chỉ nhận được lời của một vị lão tổ rằng nên bỏ qua. Sau khi rời tổ đàn, Thạch Hạo, Tào Vũ Sinh, Thạch Nghị và Tần Hạo bị phân tới những khu vực khác nhau trong Đế Thành; riêng Thạch Hạo được đưa tới một bộ lạc nhỏ chỉ còn hơn một nghìn người mang họ Thạch. Tại đây, hắn biết Thạch Tộc từng là đại tộc hùng mạnh nhưng đã suy tàn vì bị quy thành hậu duệ Tội Huyết, khiến tộc nhân qua nhiều thế hệ phải đứng ở tuyến đầu và liên tục chết trận. Đúng lúc các quan tài chiến sĩ được đưa về, A Thú nhận ra cha mình trong số người tử trận, còn bộ lạc lại mất thêm một thiên tài trưởng thành xuất sắc. Thạch Hạo xác nhận mình có chung tổ tiên với họ qua dấu ấn trên xương trán, công khai tuyên bố huyết mạch Thạch Tộc tượng trưng cho hào quang và vinh quang chứ không phải tội lỗi. Hắn quyết điều tra vụ án năm xưa, nhưng chương khép lại khi hậu nhân mới chỉ hé lộ tổ tiên Thạch Tộc từng là cường giả cái thế vô địch hậu thế."},{"chuong":1365,"tieuDe":"Thạch Tổ Chi Tội","tomTat":"Thạch Hạo truy hỏi tộc trưởng Thạch Hậu Đức về nguồn gốc danh xưng tội huyết hậu nhân và được biết tổ tiên Thạch tộc từng bị quy tội chém giết một gia tộc, cắt đầu nhiều đại nhân vật. Đối chiếu lời kể với ký ức về trận huyết chiến của Biên Hoang bảy Vương, hắn nhận ra người cầm bạch cốt đại bổng trong tranh khắc đá chính là tổ tiên Thạch tộc và tin rằng phía sau tội danh có ẩn tình lớn. Trong lúc lưu lại bộ lạc chờ xuất chinh, Thạch Hạo chứng kiến cảnh người già tàn phế và trẻ nhỏ khóc trước quan quách của những thân nhân chết trận. Hắn chỉ điểm thiếu niên trong tộc tu luyện cốt văn và Toan Nghê bảo thuật, đồng thời phát hiện A Thú có thiên phú xuất chúng. A Thú xin bái sư, còn Thạch Hạo đồng ý truyền Côn Bằng quyền để cậu học thử nhưng chưa chính thức thu nhận. Sau đó, một lão giả quen cũ dẫn năm người tới bộ lạc, kinh ngạc trước tu vi Hư Đạo cảnh của Thạch Hạo và cho biết chuyến đi liên quan đến việc xuất chinh. Do giữa hai người tồn tại cựu oán, Thạch Hạo nhận ra đối phương đến không hoàn toàn có thiện ý."},{"chuong":1366,"tieuDe":"Điều Động","tomTat":"Thạch Hạo gặp lại lão Thiên Nhân và biết đối phương đã nhờ thần đan cùng tạo hóa trong Đế quan để kéo dài sinh mệnh. Lão Thiên Nhân đề nghị điều hắn đi tìm trường sinh tiên dược ngoài quan, nhưng hắn nhận ra nhiệm vụ có thể dẫn tới cấm khu chết chóc nên lập tức từ chối. Hai bên nhắc lại cựu oán của Thiên Nhân tộc, chuyện Vân Hi và cái chết của Tế Linh, song lão Thiên Nhân phải kiềm chế sát ý vì quy củ tại Đế quan. Sau khi nhóm điều động sứ buộc người được gọi tên phải xuất quan hoặc trở về Cửu Thiên, Thạch Hạo chấp nhận lên đường và cảnh cáo bất kỳ ai có ý định hãm hại Thạch tộc. Thạch Hậu Đức, A Thú cùng đám trẻ lưu luyến tiễn hắn, khiến hắn nhớ tới cảm giác thân thuộc ở Thạch thôn. Trên đường tới điểm tập kết, Thạch Hạo biết muốn miễn tội cho hơn một nghìn người Thạch tộc phải lập chiến công tương đương khoảng mười vạn địch, nhưng hắn vẫn quyết định gánh lấy mục tiêu này. Tại diễn võ trường, hắn hỏi về giá trị đầu lâu của thành viên các Đế tộc An Lan và Du Đà rồi được một đại kỵ sĩ xác nhận rằng sinh linh trọng yếu có thể tương đương hàng nghìn, thậm chí mười vạn địch thông thường."},{"chuong":1367,"tieuDe":"Cuối Cùng Tam Đại Cảnh","tomTat":"Đại quân các tộc tập kết tại diễn võ trường để chuẩn bị xuất chinh, trong khi Ngân bào Chấp Pháp giả cố khuyên Thạch Hạo đổi sang nhiệm vụ hái Trường Sinh tiên dược. Thạch Hạo từ chối vì nhiệm vụ ấy cũng đầy nguy hiểm, đồng thời quyết định phải ra chiến trường lập công để cứu Thạch Tộc đang suy giảm xuống chưa đầy một nghìn người. Kim Chí Phi, Bát thúc của Kim Triển và là kỳ tài vừa bước vào Trảm Ngã cảnh, công khai chế nhạo Thạch Tộc rồi đối đầu gay gắt với Thạch Hạo. Đại kỵ sĩ cưỡi Thôn Thiên thú cho phép hai người luận bàn nhưng yêu cầu không được gây trọng thương hoặc làm ảnh hưởng sức chiến đấu trước lúc xuất quân. Qua cuộc đối thoại, ba cảnh giới sau Hư Đạo được xác định là Trảm Ngã, Độn Nhất và Chí Tôn, trong đó Mạnh Thiên Chính cùng Vương Trường Sinh đã đặt chân vào Chí Tôn cảnh chân chính. Kim Chí Phi cuối cùng đề nghị mỗi bên dùng một đòn thần niệm để quyết thắng, tự tin vào nguyên thần từng được dưỡng hồn thần thảo bồi dưỡng, còn Thạch Hạo bình thản chấp thuận."},{"chuong":1368,"tieuDe":"Cuối Cùng Tam Đại Cảnh","tomTat":"Đại quân các tộc tập kết tại diễn võ trường ở Đế quan để chuẩn bị xuất chinh, trong khi Ngân bào Chấp Pháp giả lần cuối khuyên Thạch Hạo cân nhắc đi hái Trường Sinh tiên dược. Thạch Hạo từ chối, nhẫn nhịn trước những lời chế nhạo về việc chuộc tội của Thạch Tộc vì mục tiêu trước mắt của hắn là cứu tộc này khỏi nguy cơ diệt vong. Kim Chí Phi, Bát thúc của Kim Triển và là cường giả vừa bước vào Trảm Ngã cảnh, công khai khinh thị rồi khiêu khích Thạch Hạo. Đại kỵ sĩ cưỡi Thôn Thiên thú ban đầu ngăn nội đấu nhưng sau đó cho phép hai người luận bàn với điều kiện không gây trọng thương. Chương đồng thời làm rõ ba đại cảnh sau Hư Đạo theo quan điểm Trường Sinh thế gia là Trảm Ngã, Độn Nhất và Chí Tôn, đồng thời xác nhận Mạnh Thiên Chính cùng Vương Trường Sinh đã đặt chân vào Chí Tôn cảnh khó dò. Kim Chí Phi đề nghị dùng thần niệm một đòn để phân thắng bại, dựa vào nguyên thần mạnh mẽ có được từ Dưỡng hồn thần thảo và quá trình rèn luyện của Kim gia. Thạch Hạo lập tức đồng ý, và chương kết thúc ngay trước khi cuộc va chạm thần niệm bắt đầu."},{"chuong":1369,"tieuDe":"Quan Ngoại","tomTat":"Sau khi Kim Chí Phi thảm bại, bị Thạch Hạo giẫm lên mặt và mất tọa kỵ, Kim gia vô cùng phẫn nộ nhưng không thể gây sự trong Đế quan. Chiến thắng khiến tu sĩ các tộc công nhận tiềm lực của Thạch Hạo, trong khi Kim Chí Phi vẫn quyết định xuất quan để ma luyện và tìm kiếm tạo hóa cổ xưa. Đại quân các tộc tiến qua Truyền Tống trận, hội quân trên tế đàn rồi dùng mảnh xương vàng mở thông lộ xuyên giới môn. Ra khỏi Đế quan, họ đặt chân lên đại sa mạc hoang lương, chứng kiến dòng sông đỏ cùng vô số hài cốt của cường giả hai giới. Đoàn quân sau đó phát hiện Địa Ngục Chi Hoa chưa trưởng thành bên một huyết tuyền và được cảnh báo rằng ma hoa này từng gây tai họa đủ sức sát hại Chí Tôn cùng sinh linh trong phạm vi rộng lớn. Trước khi cường giả Đế quan kịp tới diệt trừ, đóa hoa làm huyết tuyền khô cạn rồi độn xuống lòng đất. Khi được phép chọn nơi tìm kiếm tạo hóa, Thạch Hạo quyết định tiếp tục theo đại quân để tận mắt chứng kiến cuộc giao phong giữa hai giới."},{"chuong":1370,"tieuDe":"Thiên Uyên","tomTat":"Đại quân Cửu Thiên Thập Địa tiến sâu vào đại mạc Biên Hoang, đưa các thiên tài tới tận mắt chứng kiến chiến tranh hai giới. Các lão kỵ sĩ giải thích rằng dù phía này không còn Chân Tiên, Thiên Uyên vẫn là bình chướng có thể hút những Bất Hủ vượt giới và khiến họ biến mất. Khi nghe tòa thành cổ từng trấn giữ Biên Hoang đã lâu không xuất hiện, Thạch Hạo liên hệ điều đó với thời kỳ Đế quan phong bế và quyết điều tra chân tướng để rửa sạch nỗi oan cho Thạch Tộc. Quân Đế quan sau đó phát hiện dị vực đang dựng một đại trận khổng lồ nhằm phá hoại Thiên Uyên, mở đường cho Bất Hủ vượt giới. Các quân đoàn lập tức kết trận, triển khai lồng năng lượng phòng hộ và xung phong vào đội hình địch. Trong cuộc hỗn chiến, đại kỵ sĩ cưỡi bạch tượng giết nhiều quân dị vực nhưng bị quái vật đầu sư tử dùng thần mâu chém chết, khiến đại kỵ sĩ cưỡi Thôn Thiên thú lao xuống tiếp chiến. Thạch Hạo cũng xông vào đại quân dị vực, bắt đầu đại khai sát giới với quyết tâm dùng chiến công chuộc tội cho Thạch Tộc."},{"chuong":1371,"tieuDe":"Hai Giới Chém Giết Thượng","tomTat":"Đại mạc rộng hàng trăm nghìn dặm biến thành chiến trường đẫm máu giữa Cửu Thiên Thập Địa và dị vực, nơi ngay cả đại kỵ sĩ Độn Nhất cũng liên tiếp tử trận. Thạch Hạo dùng Bảo thuật Lôi Đế và Côn Bằng quyền giết nhiều sinh linh dị vực, rồi được một lão tu sĩ trao chiến công bài và giải thích cách ghi nhận công lao. Biết Thạch Tộc chỉ còn khoảng một nghìn người, hắn quyết định tìm săn Vương tộc, thậm chí Đế Tộc trẻ tuổi, để nhanh chóng tích lũy lượng chiến công cần thiết. Dị vực sau đó mở hàng chục lồng giam, thả một đàn cự thú chuyên dùng cho giết chóc vào trận địa. Một Vương thú vảy đen dài tám nghìn trượng nuốt nhiều tu sĩ và cắn nát lão tu sĩ vừa giúp Thạch Hạo. Thạch Hạo quay lại báo thù, triển khai Pháp tướng thiên địa và dùng Luân Hồi phá gai xương, làm đối thủ già yếu rồi đuổi kịp, xé nó thành hai nửa giữa không trung."},{"chuong":1372,"tieuDe":"Hai Giới Chém Giết Hạ","tomTat":"Thạch Hạo xé đôi Vương thú rồi dùng Luân Hồi thần thông khiến cả thân thể lẫn nguyên thần của nó già yếu, mục nát và tiêu vong, qua đó nhận thêm năm mươi chiến tích. Phía dị vực lập tức điều động Trảm Long Giả cùng nhiều cự thú Trảm Ngã cảnh vây giết hắn, buộc hắn lấy Chân Long vảy ngược ra chuẩn bị kích hoạt. Một Liệp Ma Giả thuộc thập đại thần tiễn thủ Đế quan xuất hiện và dùng đại cung bắn nổ toàn bộ các cự thú, khiến dị vực phải chuyển sang đối quyết cùng cấp. Hoàng kim Dạ Xoa trẻ tuổi được phái xuất chiến nhưng bị Thạch Hạo áp đảo về thân thể và đánh nổ bằng sức mạnh của Bất Diệt Kinh văn. Một sinh linh từng dự chiến tại Đại Xích Thiên nhận ra hắn chính là Hoang, người đã giết mười vương trẻ tuổi của dị vực. Thần tiễn thủ cùng ba đại kỵ sĩ tiến đến hộ đạo, tuyên bố sẽ ngăn mọi hành động trảm thủ vượt cấp. Được bảo vệ khỏi cuộc ám sát của cường giả cao cấp, Thạch Hạo tiến về phía đội ngũ dị vực và công khai khiêu chiến cả Vương tộc lẫn Đế Tộc trẻ tuổi."},{"chuong":1373,"tieuDe":"Đại Nhân Vật Ra Tay","tomTat":"Chiến tích chém mười Vương tại biên cương Đại Xích Thiên khiến Thạch Hạo bị dị vực nhận ra và xem là đối thủ cần phải tiêu diệt. Ngân Chu Vương chủ động khiêu chiến, dùng Thiên la địa võng hút và luyện Nguyên Thần, nhưng Thạch Hạo lần lượt vận dụng Pháp môn Côn Bằng và Bảo thuật Lôi Đế để phá thế công rồi đánh nổ đối thủ. Một cường giả Độn Nhất đỉnh cao của dị vực lập tức can thiệp, dùng bàn tay vàng định xóa bỏ Thạch Hạo, song đại kỵ sĩ Đế quan đã dùng vàng ròng giản chặn lại. Tranh chấp nhanh chóng mở rộng khi thần xạ thủ Đế quan bắn chết bốn Vương tộc, phá mũi tên nhắm vào Thạch Hạo, còn các đại kỵ sĩ tiến lên đón đánh cao thủ dị vực. Bị phía Cửu Thiên chế nhạo là khiếp sợ Hoang, lớp trẻ dị vực xin các lão tổ dừng tay để họ tự rửa nhục, khiến những cường giả cấp cao cuối cùng phải lùi lại. Cường giả trong thần hoàn màu vàng sau đó ra lệnh triệu tập Vũ Phong, Thiên Vương trẻ tuổi xếp thứ tư của dị vực, tới giết Hoang trước hai quân."},{"chuong":1374,"tieuDe":"Bất Hủ Động","tomTat":"Dị vực kích hoạt một tuyệt thế đại trận giữa chiến trường, dùng huyết quang, phù văn và bóng mờ vạn linh công kích Thiên Uyên nhằm mở đường cho Bất Hủ giả vượt giới. Thiên Uyên nhanh chóng phản phệ, làm đại trận nổ tung rồi nuốt trận kỳ, Tiên kim, vật liệu quý và cả những thống lĩnh chủ trì. Khải Dân Bất Hủ giả ra tay từ nơi xa xôi để cứu người và thu hồi vật liệu nhưng thất bại, thậm chí chiến kích của ông cũng bị Thiên Uyên lấy mất. Trên vòm trời, Mạnh Thiên Chính cùng hai lão giả phía Đế quan mang nhiều Tiên khí giằng co với mười hai lão giả dị vực đang giữ Càn Khôn Đại và hai Tiên khí tàn khuyết, song hai bên cuối cùng không giao thủ. Sau khi đối phương rút lui, Mạnh Thiên Chính cảm nhận một biến cục lớn đã đến gần. Vũ Phong được gọi đến nghênh chiến Hoang nhưng tạm hoãn vì phải thi hành pháp chỉ do An Lan và Du Đà viết, được Khải Dân chuyển giao. Hắn đặt pháp chỉ vàng lên tế đàn xương sọ, khiến pháp chỉ bốc cháy và giải phóng chữ cổ cùng âm thanh bay về phía Thiên Uyên như lời đối thoại hoặc chất vấn của hai cổ tổ."},{"chuong":1375,"tieuDe":"Xích Thiên","tomTat":"Một tế đàn luyện từ xương sọ màu đen thiêu pháp chỉ vàng của An Lan và Du Đà, giải phóng hàng nghìn phù văn vào Thiên Uyên. Uy thế của hai cổ tổ tác động trực tiếp đến linh hồn và thân thể sinh linh hai giới, khiến nhiều người mất tự chủ và muốn quỳ xuống. Mạnh Thiên Chính dùng Thập Giới Đồ chặn uy áp, bảo vệ phe Cửu Thiên Thập Địa. Thiên Uyên sau đó phun tinh khí trắng và phóng những dây xích trật tự đỏ đậm, xuyên thủng rồi tiêu diệt toàn bộ phù hiệu trên pháp chỉ. Từ phần cổ văn còn nhận ra được, Mạnh Thiên Chính cho biết An Lan và Du Đà muốn tìm một vật bí ẩn, tiếp dẫn vài đạo huynh trở về và vì thế nhất định phải vượt Thiên Uyên để tiến vào Đế quan. Khả năng tồn tại những sinh linh được hai cổ tổ gọi là đạo huynh khiến phía Cửu Thiên lo ngại về mục đích thật sự của cuộc xâm nhập. Cuối cùng, ông lão cầm Càn Khôn Đại bước ra, công khai yêu cầu đối phương sớm giao vật mà Dị vực đang tìm kiếm."},{"chuong":1376,"tieuDe":"Đồng Đại Không Thể Địch","tomTat":"Mạnh Thiên Chính tuy chưa biết vật mà Dị vực đòi hỏi là gì vẫn khẳng định nó thuộc về Cửu Thiên, trong khi lão giả Dị vực cũng chỉ suy đoán từ những mảnh cổ tổ văn tự trên pháp chỉ. Lão giả dùng ánh mắt giết một chiến tướng Cửu Thiên, khiến thần xạ thủ lập tức bắn chết bốn cường giả Dị vực để trả đũa. Mạnh Thiên Chính hóa giải sát cơ, công khai áp đảo đối phương rồi cùng lão ẩn vào bóng tối kiềm chế lẫn nhau để tránh một trận chiến cấp Chí Tôn gây thương vong vô tận. Thống lĩnh Dị vực sau đó ra lệnh cho Vũ Phong chém đầu Thạch Hạo nhằm rửa nhục cho những vương giả trẻ tuổi từng thất bại. Vũ Phong vận chuyển Bất Hủ Thiên Đao quyết cùng tổ thuật thần bí, còn Thạch Hạo âm thầm dùng Bất Diệt Kinh và liên tiếp đánh ba quyền vào Thiên Đao ấn. Khi pháp chỉ không thể uy hiếp Thiên Uyên, kèn lệnh Bất Hủ vang lên triệu hồi quân Dị vực rút lui dưới sự đoạn hậu của lão giả cầm Càn Khôn Đại. Tới tận đường chân trời, Vũ Phong mới thổ huyết, để lộ cánh tay phải rạn nứt và thừa nhận Thạch Hạo gần như không có đối thủ trong cùng thế hệ."},{"chuong":1377,"tieuDe":"Chỉ Vì Luyện Binh","tomTat":"Tiếng kèn lệnh vang lên, đại quân dị vực rút khỏi đại mạc dưới sự đoạn hậu của ông lão cầm Tiên khí Càn Khôn Đại, còn quân Đế quan cũng mang người sống, thi thể và quan tài trở về. Một đại kỵ sĩ nói rõ các cuộc xuất quan đẫm máu là quá trình luyện binh, nhằm mài giũa chiến sĩ Thiết Huyết cho ngày Thiên Uyên biến mất và trận quyết chiến bùng nổ. Trước khi vào Đế quan, đoàn quân bị cổ kính soi xét; những sinh linh dị vực trà trộn lập tức hiện nguyên hình rồi hóa thành tro, trong khi Thạch Hạo vượt qua sự xác minh nhờ huyết dịch và dấu ấn thần hồn cộng hưởng với hùng quan. Thiên Giác Nghĩ trở lại bên hắn sau trận chiến, còn thất bại của Vũ Phong khiến thế hệ trẻ dị vực xem Hoang là đại địch và cân nhắc mời cả người thuộc Đế Tộc xuất thế. Trở về bộ lạc Thạch Tộc, Thạch Hạo được A Thú, Thạch Hậu Đức và dân làng đón tiếp trong niềm vui xen lẫn nỗi đau của những gia đình mất người thân. Cảm nhận được sự chân thành ấy, hắn quyết định chọn bộ lạc làm nơi đặt chân duy nhất, dành nửa tháng dạy trẻ và suy diễn con đường đại đạo. Sau đó, một sứ giả mang thiệp mời Hoang dự cuộc tụ hội quy tụ tinh anh Cửu Thiên, truyền nhân mạnh nhất Đế quan, hậu duệ vô địch giả và hậu duệ Chân Tiên."},{"chuong":1378,"tieuDe":"Thiên Tài Thịnh Hội","tomTat":"Người truyền tin tới nơi nghỉ chân của Thạch Hạo để giới thiệu những thiên tài sẽ dự hội và chuyển thiệp mời tới Bích Lạc hồ. Thiên Giác Nghĩ coi nhẹ hậu duệ Chân Tiên, còn Thạch Hạo phải công khai thân phận Thập Hung của nó, khiến người truyền tin hoảng sợ rời đi. Tào Vũ Sinh vừa xuất quan đã kể chuyện mình đánh người truyền tin vì không được mời, sau đó kiên quyết kéo Thạch Hạo cùng đi dự hội. Trong Đế quan lan truyền tin thịnh hội sẽ trưng bày kỳ trân từ dị vực, tàn đồ liên quan Trường Sinh dược và bàn luận bí mật vùng cấm. Việc một thiệp mời được gửi vào vùng cấm trên chín tầng trời gây chấn động vì những nơi ấy lâu nay gần như không có sinh linh xuất thế. Sau ba ngày, Thạch Hạo, Tào Vũ Sinh và Thiên Giác Nghĩ tới Bích Lạc hồ giữa quần sơn phủ tiên vụ, chủ yếu để chờ xem sinh linh vùng cấm có thật sự xuất hiện hay không."},{"chuong":1379,"tieuDe":"Cường Giả Tập Hợp","tomTat":"Thạch Hạo, Tào Vũ Sinh và Thiên Giác Nghĩ đến gần Bích Lạc hồ, chứng kiến cảnh sắc linh tú cùng Vệ gia Tứ Hoàng tiến vào khu vực tổ chức thịnh hội. Ngũ linh chiến xa sau đó xuất hiện, chở Tề Hoành và Kim Triển tới nơi trong sự nghênh đón long trọng của nhiều cường giả trẻ tuổi. Trước khả năng Kim Triển sẽ thay Vương gia đối đầu mình, Thạch Hạo quyết định không chủ động gây xung đột vì nguy cơ đại quân Dị Vực phá Biên Hoang cấp bách hơn. Hai Thiểm điện chiến xa của Thác Cổ gia tộc tiếp tục tới hồ, với Thác Cổ Ngự Long đi đầu còn Thác Cổ Lạc Nhạn và Vương Hi ở phía sau. Tào Vũ Sinh và Thiên Giác Nghĩ nghi ngờ các thế gia đang chia đường kết giao với những truyền nhân mạnh, nhưng Thạch Hạo cho rằng chiến lực cá nhân đạt tới cực hạn mới quyết định cục diện khi đại biến xảy ra. Cuối chương, Tiểu Thiên Vương, Đại Tu Đà, Thích Cố, Lam Tiên cùng nhiều tu sĩ trẻ tuổi Đế Quan lần lượt hội tụ, khiến thịnh hội quy tụ đông đảo thiên kiêu."},{"chuong":1380,"tieuDe":"Là Hoang","tomTat":"Thạch Hạo và Tào Vũ Sinh theo dòng nước tiến vào Bích Lạc hồ, nơi thiên tài các tộc đang tụ hội giữa tin đồn sinh linh vùng cấm có thể tới Đế quan. Khi đại hội bắt đầu, một hòn đảo xanh biếc nghi là di chỉ Chân Tiên nổi lên giữa hồ và tỏa ra Tiên Đạo khí tức, trở thành nơi mọi người tập trung. Trên đảo, người đưa tin nhận ra Tào Vũ Sinh rồi kích động thanh niên tóc tím phụ trách trật tự chất vấn hắn về thiệp mời. Tào Vũ Sinh phản bác rằng người của Kim gia và Vương gia cũng được dẫn vào, qua đó vạch ra cách áp dụng quy định không đồng đều. Thạch Hạo bước ra can thiệp, khiến người đưa tin báo nhỏ thân phận của hắn và thanh niên tóc tím lập tức đổi thái độ khi biết mình đang đối mặt với Hoang. Tề Hoành, Vệ gia Tứ Hoàng và Thác Cổ Ngự Long lần lượt tới chào hỏi, công khai chiến tích Thạch Hạo từng giết mười Vương dị vực tại Đại Xích Thiên biên cương. Đông đảo tu sĩ Đế quan và Cửu Thiên chen tới bày tỏ kính phục, trong khi Kim Triển, Vương Hi và Ninh Xuyên vẫn giữ thái độ lạnh nhạt hoặc im lặng."},{"chuong":1381,"tieuDe":"Đáng Chém","tomTat":"Thân phận Hoang được công khai tại thịnh hội Bích Lạc hồ, khiến đông đảo người trẻ sinh trưởng trong Đế quan vây quanh Thạch Hạo để hỏi về trận chiến Biên Hoang và bày tỏ sự kính phục. Thiên Giác Nghĩ thu hút sự chú ý vì huyết mạch kiện toàn, nhưng bất mãn khi bị coi là sinh vật đáng yêu hoặc chiến thú, buộc Thạch Hạo phải nói rõ hai người là huynh đệ. Tề Hoành mời Thạch Hạo, Thiên Giác Nghĩ và Tào Vũ Sinh vào khu ghế trung tâm, song Kim Chí Phi nhanh chóng xuất hiện, định bắt Tào Vũ Sinh và đòi tái chiến với Thạch Hạo để rửa nhục. Tề Hoành, Thác Cổ Ngự Long và một thiếu nữ Vệ gia cùng phản đối việc gây chiến tại buổi tụ hội, trong khi Kim Triển và Vương Hi đứng về phía Kim Chí Phi. Khi Kim Chí Phi chuẩn bị rời đi, một hậu bối trực hệ Kim gia cùng chiến phó liên tục nhục mạ Thạch Hạo và đòi hắn rời khỏi Đế quan. Thạch Hạo bất ngờ hóa ra bàn tay lớn màu vàng, giết cả hai ngay trước mặt Kim Chí Phi và Kim Triển. Sau đó hắn tuyên bố mình không tham gia một cuộc khiêu chiến vô vị mà chỉ sát sinh, đồng thời phán những kẻ tùy tiện gây rối tại thịnh hội là đáng chém."},{"chuong":1382,"tieuDe":"Khiêu Chiến","tomTat":"Kim Chí Phi nổi giận sau khi Thạch Hạo giết người Kim gia, bất chấp Tề Hoành can ngăn và công khai đòi trảm Hoang. Tào Vũ Sinh cùng Thiên Giác Nghĩ đứng về phía Thạch Hạo, nhắc lại thất bại trước đây của Kim Chí Phi và xác nhận phía Kim gia đã chủ động khiêu khích. Kim Triển xuất hiện sau tộc thúc, lấy cái chết của một tộc đệ làm lý do yêu cầu Thạch Hạo đền máu. Vương Hi viện quy củ Đế quan về tội tùy ý hành hung, nhưng Thạch Hạo phản biện bằng ngoại lệ dành cho kẻ chủ động nhục mạ và mở chiến đoan, được Vệ gia Tứ Hoàng xác nhận. Cuộc tranh chấp cuối cùng được chuyển thành quyết đấu, còn Bích Lạc đạo đài được chọn làm chiến trường để tránh phá hỏng nơi tổ chức thịnh hội. Trước đạo đài, Thạch Hạo thách Kim Chí Phi, Kim Triển và Vương Hi cùng liên thủ. Kim Chí Phi lập tức lao lên, còn Thạch Hạo đón đánh, khiến trận chiến chính thức bùng nổ."},{"chuong":1383,"tieuDe":"Thiên Kiếp Chúa Tể","tomTat":"Kim Chí Phi mở màn bằng ba loại bảo thuật gồm sấm sét, Nhai Tí diễn hóa và sát kiếm, buộc Thạch Hạo phải dùng Bảo thuật Lôi Đế dẫn động sức mạnh thiên địa để hóa thành biển sét. Lôi đình của Thạch Hạo lần lượt hấp thu tia điện, đánh tan Nhai Tí và phá hủy kiếm khí đối phương. Kim Chí Phi tiếp tục tế ra huyết sắc pháp kiếm, nhưng Thạch Hạo dùng Đại La kiếm thai chém gãy hung khí thành hai đoạn. Sau đó, Kim Chí Phi diễn hóa Kim Cương Tiên thiên công, còn Thạch Hạo mở Lục Đạo Luân Hồi để đối đầu, khiến hai môn cổ thiên công cùng tan vỡ và cả hai người đều bị thương. Khi Kim Chí Phi đẩy thiên công đến cực hạn, sấm sét bất ngờ phủ kín trời đất trong khi Thạch Hạo đứng giữa lôi quang mà không bị xâm hại. Kim Triển nhận ra Thạch Hạo đã lĩnh hội hàm nghĩa cao nhất của Lôi Đế pháp và đang diễn hóa thiên kiếp dựa theo pháp thể Kim Chí Phi, nên lập tức cảnh báo tiểu thúc rút lui."},{"chuong":1384,"tieuDe":"Đối Lập","tomTat":"Sau khi Kim Chí Phi vượt lôi kiếp thất bại, Thạch Hạo chém đầu hắn, cầm cố Nguyên Thần trong đầu lâu và để Lôi Trì luyện hủy thân thể. Thiên Giác Nghĩ, Thái Âm Ngọc Thỏ và Tào Vũ Sinh đem bình ra chế nhạo chuyện ướp muối chiến bại, khiến Kim Triển nổi giận muốn quyết chiến với Hoang. Vương Hi cùng trưởng bối hai nhà Kim, Vương ngăn Kim Triển ra tay vì hai tộc đang vun đắp hắn thành đệ nhất nhân thế hệ trẻ và không muốn hắn chịu thất bại. Khi các trưởng bối định can thiệp, Thạch Hạo điều động Lôi Trì phá một bàn tay của Mười hai thúc tổ Vương Hi rồi bức Ngũ thúc tổ Kim Triển lui tránh. Tề Hoành và Thác Cổ Ngự Long xin tha Kim Chí Phi để giữ lại một cường giả cho chiến trường Biên Hoang, nên Thạch Hạo trả đầu nhưng buộc hắn phải ra quan ngoại giết địch lập công. Sau khi thiếu nữ trong Tứ Hoàng điều giải, Thạch Hạo ngồi giữa lôi kiếp, bế quan cảm ngộ Bảo thuật Lôi Đế và suy tư con đường chưởng ngự thiên kiếp."},{"chuong":1385,"tieuDe":"Ngộ Đạo","tomTat":"Sau khi chém đầu Kim Chí Phi, Thạch Hạo bế quan ngay tại chỗ và quyết định dẫn Thiên Kiếp luyện thể, bất chấp lời cảnh báo rằng thiên phú của hắn có thể dẫn tới một trong những đại kiếp mạnh nhất từ cổ chí kim. Trước lúc độ kiếp, hắn giao Đả Thần Thạch đang ngủ say lột xác và Hoàng Điệp đang kết kén cho Tào Vũ Sinh, Thiên Giác Nghĩ cùng những người bên cạnh giữ giúp. Thiên lôi bất ngờ tan đi, khiến Thạch Hạo chuyển sang suy ngẫm con đường chưởng ngự Thiên Kiếp của Lôi Đế và quan tưởng một Lôi Trì nhỏ trước mi tâm. Thúc tổ của Vương Hi muốn bí mật phá hoại quá trình ngộ đạo, nhưng Vương Hi phản đối vì lo Vương gia mất mặt, còn Kim Triển tuyên bố sẽ trực tiếp tiến vào lôi hải tranh bá với Thạch Hạo. Lôi Trì quan tưởng sau đó nổ tung mà không làm Thạch Hạo bị thương, điện quang hội tụ thành ấn ký Lôi Trì trên xương trán, chứng minh hắn đã có thu hoạch thực chất. Các thiên kiêu hàng đầu đều trở nên nghiêm nghị trước thành quả ấy. Khi Thạch Hạo mở mắt chuẩn bị dẫn kiếp, một bóng đen khổng lồ mang theo áp lực như sinh vật sống bắt đầu ép xuống từ vòm trời."},{"chuong":1386,"tieuDe":"Cửu Thiên Thập Địa Kiếp","tomTat":"Thiên kiếp của Thạch Hạo không giáng xuống theo hình thức lôi đình thông thường mà diễn hóa thành mười đại lục thuộc Thập Địa, trong đó có hình dạng của Ba Ngàn Châu và Khởi Ma. Trên các đại lục hiện ra núi sông, vạn vật, thi hài, chiến kỳ và máu đọng như tàn tích của một trận đại chiến hủy diệt Tiên cổ. Chín tầng trời tiếp tục xuất hiện phía trên, tái hiện cảnh tiên dân liều chết chống đại quân dị vực để bảo vệ thân nhân và non sông. Kim Triển xác nhận toàn bộ cảnh tượng gần như chân thực này chính là thiên kiếp, còn những người quan sát nghi nó có thể hé lộ một góc tương lai. Khi Cửu Thiên và Thập Địa nối liền bằng những cầu sấm sét, Thạch Hạo bị một lực lượng mạnh hút lên một đại lục. Hắn dùng một ngón tay đánh gãy chiến mâu lôi điện của một thi thể dị vực, nhưng ngay sau đó vô số thi thể khác đồng loạt đứng dậy, mang sát ý và binh khí vây công hắn."},{"chuong":1387,"tieuDe":"Giết Tới Cửu Thiên","tomTat":"Thạch Hạo bị đại quân dị vực do Thiên Kiếp diễn hóa vây công trên đại lục đầu tiên, nhưng hắn vận dụng Thượng Thương đánh chết thủ lĩnh mặt người thân sư tử. Hắn tiếp tục ngưng tụ trường thương bằng thần lực, xuyên thủng và quét nát nhiều chiến binh, trong khi mỗi kẻ bị giết lại hóa thành lôi quang công kích thân thể hắn. Lực lượng giam cầm của Thiên Kiếp khiến hắn không thể trực tiếp bay lên mà phải lần lượt vượt qua các vùng của Cửu Thiên Thập Địa bằng Lôi Điện phù kiều. Khi chiến mâu, tên và trường đao lôi đình cắm đầy thân thể, hắn vận chuyển Bảo thuật Lôi Đế để ép chúng ra ngoài rồi cho phát nổ. Thạch Hạo sau đó chém sinh linh Trảm Ngã cảnh mang một phần huyết mạch Vương tộc, rời khỏi đại lục tương ứng với Ba Ngàn Châu và tiếp tục huyết chiến qua những chiến trường kế tiếp. Dù nhiều lần trọng thương ngã xuống, hắn vẫn đứng dậy tiến lên, cuối cùng vượt hết Thập Địa và đặt chân tới Cửu Thiên."},{"chuong":1388,"tieuDe":"Soạn Nên Truyền Kỳ","tomTat":"Thạch Hạo vượt cầu nổi từ chiến trường Thập Địa lên Cửu Thiên, nơi quân dị vực mạnh hơn đang áp đảo tiên dân, và tinh thần tử chiến của những người bảo vệ quê hương khiến hắn tiếp tục huyết chiến. Hắn giao chiến suốt nghìn hiệp với một thống lĩnh Vương tộc thuần huyết ở Trảm Ngã cảnh, dùng duy nhất động thiên phá tổ thuật ngân hóa rồi dung hợp nhiều bảo thuật vào đao lôi đình để chém đôi cả đối thủ lẫn chiến thú. Lôi điện do vương giả đã chết biến thành khiến thân thể hắn cháy đen, nứt vỡ và chảy máu. Trên đường tiến lên, Thạch Hạo chứng kiến dân thường trong một thôn xóm bị tàn sát, liền giết tên đao phủ cùng hàng trăm sinh linh dị vực nhưng không thể thay đổi cảnh tượng lịch sử do lôi kiếp tái hiện. Những thành trì giống đương đại khiến hắn nghi ngờ thảm kịch này có thể là báo hiệu cho tương lai của Cửu Thiên Thập Địa. Tiến vào Đại Hoang, hắn bị hàng chục vạn rồi hơn triệu Ngân Sắc Ngô Công vây công và nhiều lần cận tử nhưng vẫn giết thoát. Với thân thể huyết nhục tan nát, Thạch Hạo liên tiếp vượt các tầng sáu, bảy và tám để bước lên tầng trời thứ chín. Người quan chiến kinh ngạc trước thành tựu chưa từng có và công nhận Hoang đang viết nên một truyền kỳ vô địch."},{"chuong":1389,"tieuDe":"Tầng Thiên Cuối Cùng","tomTat":"Thạch Hạo vượt qua tầng tám và đặt chân lên tầng trời thứ chín trong tình trạng gần kiệt quệ, thân thể rách nát và trước ngực có một lỗ thủng lớn. Tầng cuối vừa mang sức hủy diệt khủng khiếp vừa ẩn chứa sinh cơ, cho phép hắn hấp thu lực sống trong lôi quang để nối xương và khôi phục huyết nhục. Ngay khi vừa lấy lại khả năng chiến đấu, hắn bị một sinh linh dùng bạch kim thần kiếm tập kích và buộc phải tái chiến. Thạch Hạo cầm trường đao giết xuyên thiên quân vạn mã dị vực, đồng thời vận dụng Pháp môn Côn Bằng để tăng thế công và chém đầu Mộc Thác Vương. Những tu sĩ Cửu Thiên Thập Địa xông lên cứu viện, có người hy sinh để giúp hắn giữ lại cơ hội sống và tiếp tục tiến sâu vào chiến trường. Sau nhiều đợt vương giả cùng cường giả trẻ tuổi nhập cuộc, đại quân bất ngờ lùi ra, nhường chỗ cho các kim quang đại đạo từ bốn phương kéo tới. Mỗi con đường chỉ có một sinh linh trẻ tuổi đáng sợ, khiến người quan sát suy đoán họ là những thành viên Đế Tộc đã ngủ đông từ lâu."},{"chuong":1390,"tieuDe":"Đế Tộc","tomTat":"Khái niệm Đế tộc tại Cửu Thiên Thập Địa và Dị Vực được phân biệt, trong đó Đế tộc Dị Vực là hậu duệ của những Cổ Tổ Bất Hủ như An Lan và Du Đà. Những manh mối từ một cổ táng địa bí ẩn còn khiến các cường giả Dị Vực nghi ngờ có con đường hoặc sinh linh vượt trên lĩnh vực hiện tại của họ, nhưng giả thuyết này chưa được xác thực. Trong thiên kiếp, nhiều hậu duệ Đế tộc đi theo các kim quang đại đạo tới vây kín Thạch Hạo, khiến Tào Vũ Sinh, Thiên Giác Nghĩ và Thái Âm Ngọc Thỏ vô cùng lo lắng. Một nam tử Đế tộc tung quyền thăm dò nhưng quyền quang bị lôi điện của Thạch Hạo chặn lại. Tiếp đó, nữ hậu duệ An Lan kích hoạt ma văn trường thương trên cánh tay, thi triển An Lan chi mâu đối đầu Luân Hồi quyền và sức mạnh thời gian của Thạch Hạo. Khi cuộc đối đầu chưa phân thắng bại, những hậu duệ Đế tộc còn lại đồng loạt tiến lên, chuẩn bị vận dụng Tổ thuật để hợp kích Hoang."},{"chuong":1391,"tieuDe":"Tuyệt Vọng Chi Cảnh","tomTat":"Trên kim quang đại đạo, nhiều hình bóng hậu nhân Đế tộc cùng cảnh giới đồng loạt vây giết Thạch Hạo, khiến những người quan chiến gần như tin rằng hắn chắc chắn sẽ chết. Thạch Hạo kích phát Chí Tôn thuật thứ ba, lần đầu làm rõ khả năng gia tăng uy lực cho các bảo thuật khác, rồi dùng Luân Hồi đã được cường hóa đánh gãy Hoàng Kim trường thương của An Lan nhất tộc. Nữ hậu nhân An Lan lập tức chuyển sang An Lan Diệt Thế Quyết, trong khi các hình bóng còn lại dùng đại kích, chiến mâu, thần kiếm, thần lô và tổ thuật liên tiếp hợp kích. Dù vận chuyển Lục Đạo Luân Hồi và điệp gia Thượng Thương, Luân Hồi cùng Chí Tôn thuật thứ ba, Thạch Hạo vẫn bị nhiều binh khí xuyên thân và gần tan xác. Hắn tiếp tục gọi Lôi Trì giáng kiếp lên quần đế, nhưng không thể áp đảo số đông và lại bị đánh đến nhục thân vỡ nứt. Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Thiên Giác Nghĩ tuyệt vọng cổ vũ hắn sống sót, còn các trưởng bối đối địch tin rằng kết cục đã được định đoạt. Thạch Hạo vẫn không chịu khuất phục và khẳng định mình là mạnh nhất giữa lúc đế quang xuyên thủng cơ thể. Cuối chương, thân thể hắn bất ngờ chia thành một nửa kim sắc và một nửa đen như vực sâu, đồng thời phát ra dao động bí ẩn."},{"chuong":1392,"tieuDe":"Đạp Con Đường Của Chính Mình","tomTat":"Bị nhiều hậu nhân Đế tộc liên thủ dùng vô thượng tổ thuật trấn ép, Thạch Hạo khai phóng tiềm năng thân thể và đẩy Côn Bằng pháp tới cực hạn, diễn hóa sức mạnh Thái Âm và Thái Dương thành Âm Dương đồ. Hắn tiếp tục khiến Liễu Thần pháp quy về nguyên thủy, nhìn thấy một phần bí mật của pháp này và cùng ngày nắm giữ chân lý tối cao của ba loại bảo thuật lớn. Tuy nhiên, những thành quả ấy vẫn không đủ giúp hắn áp chế toàn bộ đối thủ; dù vận chuyển Nguyên Thủy Chân Giải và Bất Diệt Kinh, hắn vẫn bị đánh nổ thân thể rồi phải dùng cành liễu kéo các phần tàn thể trở lại để tái tổ hợp. Nhận ra các truyền thừa mạnh mẽ kia không phải con đường do mình khai sáng, Thạch Hạo quyết định dung hợp kiếp này pháp, Tiên cổ pháp và phương pháp tự tìm tòi để xây dựng hệ thống riêng. Hắn thu nhỏ duy nhất động thiên, đưa nó vào bụng làm cực điểm rồi dung nhập Âm Dương đồ, Lôi Trì, lôi kiếp dịch và nguyên thủy khí. Ba đạo tiên khí cùng Tiên cổ kinh văn được dùng để bảo vệ những cánh cửa kho tàng huyết nhục quanh vùng bụng trước khi cực điểm bạo phát. Thạch Hạo gọi bước đầu tiên trên con đường mới là Luân Hải, nhưng chương kết thúc trước khi kết quả khai mở được xác nhận."},{"chuong":1393,"tieuDe":"Mỡ Ra","tomTat":"Trước vòng vây của các cao thủ Đế tộc, Thạch Hạo cho duy nhất động thiên nổ tung tại vùng bụng, quyết dùng nơi tập trung nhiều cánh cửa nhất để khai sáng con đường tu luyện riêng. Vụ nổ mở hàng loạt cửa nhưng cũng khiến thân thể hắn gần như tan vỡ, đồng thời dẫn phát mưa máu, thiên khóc, cổ thi và nhiều dị tượng kinh người. Thạch Hạo hợp nhất Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp thành âm dương thần đồ, lại vận chuyển tiên kinh cùng ba đạo tiên khí để trấn áp hỗn loạn và chữa trị thương thế. Đòn hợp kích của Đế tộc xuyên qua màn sáng, song quá trình đối kháng lại vô tình dẫn bớt sức hủy diệt khỏi cơ thể hắn, giúp hắn vượt qua giai đoạn nguy hiểm nhất. Sinh cơ và tử khí từ những cánh cửa tại bụng sau đó liên kết thành đổi phiên hải, vận chuyển tuần hoàn và nối với toàn thân để thu nhận lực lượng. Khi căn cơ mới bước đầu thành hình, hàng chục lớp dị tượng cát tường xuất hiện, còn Thạch Hạo chủ động chuẩn bị giao chiến để kiểm nghiệm chiến lực. Trước khi hai bên kịp tái chiến, một vật chưa rõ lai lịch mang theo tiên khí bất ngờ rơi xuống từ lôi quang và phóng thích tiên quang bất hủ."},{"chuong":1394,"tieuDe":"Trảm Tiên Đài","tomTat":"Một Trảm Tiên Đài mang dao cầu giáng xuống trong thiên kiếp của Thạch Hạo, được cho là hình phạt do hắn tự mở con đường tu luyện khác biệt. Thiên Giác Nghĩ trả Đại La kiếm thai để giúp hắn chống kiếp, nhưng Thạch Hạo ném trả vì hiểu rằng ngoại vật không thể giúp mình tránh khỏi đạo đài này. Trảm Tiên Đài phong tỏa khu vực, cầm cố rồi chém diệt cả thân thể lẫn Nguyên Thần của những bóng dáng Đế Tộc do thiên kiếp hiển hóa. Sau đó, tiên quang trói Thạch Hạo lên đạo đài và dao cầu chém rơi đầu hắn, khiến bạn bè tuyệt vọng trong khi người của Vương gia và Kim gia vui mừng. Khi mọi người đều tin hắn đã chết, thi thể không đầu bất ngờ đứng dậy, tự đặt đầu trở lại cổ và gọi toàn bộ máu đã chảy ra về cơ thể. Thạch Hạo đã sống qua nhát chém và bảo toàn Nguyên Thần, nhưng phương pháp giúp hắn làm được điều đó vẫn chưa được hé lộ."},{"chuong":1395,"tieuDe":"Phục Sinh Bí Mật","tomTat":"Sau khi bị Trảm Tiên đài chém đầu, Thạch Hạo tự đặt đầu trở lại cổ, khiến vết thương khép kín, tinh huyết chảy ngược và sinh cơ hoàn toàn phục hồi. Những người chứng kiến chấn động; Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Thiên Giác Nghĩ vui mừng, trong khi các trưởng bối Vương gia và Kim gia lo hắn sẽ trở thành đại họa. Thạch Hạo nhận ra sinh linh trên Đại đạo chi hoa đã rời Luân Hải, nhập vào đầu lâu và tạm hợp nhất với nguyên thần để chết thay mình. Luân Hồi ấn thứ năm giữ sinh linh ấy không tan biến nhưng đồng thời hóa thành gông xiềng trấn áp nó. Khi Trảm Tiên đài tan thành lôi quang và thiên kiếp chấm dứt, Lôi Trì xuất hiện, nhỏ Lôi kiếp dịch xuống giúp Thạch Hạo chữa sạch thương thế và tái tạo xương gãy. Giữa lúc mọi người thèm muốn tạo hóa này, Vương Hi thúc tổ bí mật nhận một vật xuyên hư không và chuẩn bị thủ đoạn phá hủy đạo quả của Thạch Hạo."},{"chuong":1396,"tieuDe":"Lôi Linh","tomTat":"Vương gia căm thù Thạch Hạo vì năm Long trong tộc bị đày tới Đế quan, nên Vương Đại giao một hộp đá chứa Lôi Linh cho Vương Hi thúc tổ để phá hoại thiên kiếp của hắn. Trong lúc đó, Thạch Hạo hấp thu lôi kiếp dịch để tái tạo thân thể và phát hiện Lôi Trì tại tầng trời thứ chín chỉ là phó trì, phía trên còn có Lôi Trì tầng thứ mười chứa hỗn độn cùng tiên khí. Dù đã đủ điều kiện tiến vào Trảm Ngã cảnh, hắn quyết định tạm hoãn đột phá để củng cố đạo cơ và giúp ba đạo tiên khí bén rễ vững chắc. Tiên Đạo kinh văn cùng con đường Luân Hải do hắn tự mở lần lượt hấp thu lôi kiếp dịch, lôi đình và sức mạnh hủy diệt rồi phản hồi năng lượng cho toàn thân. Chờ lúc Thạch Hạo chìm sâu trong ngộ đạo, Vương Hi thúc tổ mở hộp đá và thả ba Lôi Linh màu trắng bạc, vàng kim và đỏ sậm vào thiên kiếp. Lôi Linh đỏ sậm lao tới định giết Thạch Hạo và đoạt tạo hóa nhưng bị ánh chớp đánh trúng, khiến hắn tỉnh lại và nhận ra âm mưu phá hoại đạo quả. Thạch Hạo nổi giận, khẳng định sẽ không bỏ qua kẻ đã mưu hại mình."},{"chuong":1397,"tieuDe":"Hàng Phục","tomTat":"Một con Lôi Linh đỏ sậm xâm nhập thiên kiếp, tập kích mi tâm Thạch Hạo và tìm cách cướp tạo hóa trong Lôi Trì. Vì Thạch Hạo đã hoàn thành phần độ kiếp và được thiên kiếp thừa nhận, kẻ xâm nhập liên tiếp bị sét hỗn độn đánh thương. Khi nó hóa thành huyết mâu tiếp tục tấn công, Thạch Hạo vận chuyển Bất Diệt Kinh văn, dùng thân thể đối kháng rồi áp chế và bắt sống nó. Hai Lôi Linh vàng bạc dẫn theo đại quân sinh linh chớp giật đến cứu viện nhưng bị Thạch Hạo đánh tan, buộc phải xuyên hư không bỏ trốn. Nhờ thần giác cùng liên hệ giữa ba Lôi Linh, Thạch Hạo truy tới chỗ Vương Hi và phát hiện hai con đang ẩn trên người ông lão bên cạnh nàng. Vương Hi chất vấn hắn, còn Kim Triển định tiến lên cản trở nhưng bị Thạch Hạo cảnh cáo rằng nếu không lui sẽ lập tức bị giết."},{"chuong":1398,"tieuDe":"Nộ Sát","tomTat":"Thạch Hạo phát hiện hai Lôi Linh được bố trí nhằm hại mình lúc độ kiếp nên công khai vạch trần âm mưu của Vương gia, trong khi Tào Vũ Sinh cùng đồng bạn lớn tiếng truyền sự việc khắp Đế quan. Cao tầng Vương gia thất bại khi bí mật thu hồi hộp đá, sau đó từ bỏ thúc tổ của Vương Hi và buộc ông ta mở hộp thả hai thần trùng. Thạch Hạo truy bắt Lôi Linh, còn một đại nhân vật ngăn kẻ khác cướp chúng và xác lập quyền hàng phục cho Hoang. Đúng lúc ấy, Hoàng Điệp hoàn tất nhiều năm lột xác, phá kén xuất thế và dùng đôi cánh vàng trấn áp cả hai Lôi Linh. Thạch Hạo quay lại tính sổ, áp đảo thúc tổ của Vương Hi cùng thúc tổ của Kim Triển rồi lần lượt giết chết cả hai. Kim Triển bùng lên sát ý nhưng bị người từ xa ngăn lại, còn Vương Hi kinh hãi chứng kiến thúc tổ bỏ mạng."},{"chuong":1399,"tieuDe":"Mạnh Mẽ Tổ Hợp","tomTat":"Cái chết nhanh chóng của hai cao thủ Trảm Ngã khiến các tu sĩ trên Bích Lạc đảo kinh hãi, còn Kim gia và Vương gia lần lượt dùng cánh cửa không gian đưa Kim Triển cùng Vương Hi rời khỏi hiện trường. Trong lúc đó, Hoàng Điệp lấy một địch hai, giao chiến hơn bốn trăm chiêu rồi dùng đôi cánh vàng trấn áp hai Lôi Linh. Thạch Hạo tự tay phong ấn chúng, cất cùng con thứ ba và dự định bồi dưỡng cả ba thành chiến phó. Sau khi luyện hóa sạch lôi kiếp dịch còn lại ở tầng trời thứ chín, hắn xông lên tầng thứ mười bất chấp lôi đình dữ dội. Tại Lôi Trì cuối cùng, hắn dùng cốt đỉnh thu lấy chất lỏng đỏ óng có sức mạnh vượt xa linh dịch tầng trước. Nhận ra chiếc ao dường như được đào từ cổ nham thạch thật và mang khí tức Tiên Đạo, Thạch Hạo vận dụng thần thông thử nhổ cả Lôi Trì để cất đi, nhưng chương kết thúc trước khi xác nhận hắn có thành công hay không."},{"chuong":1400,"tieuDe":"Gan To Bằng Trời","tomTat":"Sau khi lấy lôi kiếp dịch, Thạch Hạo quyết đoạt cả Lôi Trì có thực thể, bất chấp hơn chín nghìn đạo lôi điện cùng đánh xuống và liên tục vận dụng Luân Hải, lực Côn Bằng, Liễu Thần pháp cùng nhiều pháp môn khác. Khi thiên kiếp sắp kết thúc, các khe nứt kỳ dị xuất hiện trên vòm trời để hút lôi quang về một nơi bí ẩn, còn Lôi Trì kéo hắn về phía đó khiến Mạnh Thiên Chính và các đồng bạn liên tục cảnh báo. Thạch Hạo vẫn cưỡng ép thu cổ trì vào Luân Hải, chọc giận thiên kiếp và bị hàng nghìn hàng vạn tia chớp hòa Hỗn Độn khí xuyên thủng thân thể. Trảm Tiên đài vì thế lần thứ hai ngưng tụ trong cùng một lần thiên kiếp, hiện ra dao cầu đỏ sậm chuẩn bị chém xuống, buộc hắn vận chuyển Bất Diệt Kinh và Nguyên Thủy Chân Giải tới cực hạn để chống đỡ. Đến khi các khe nứt khép kín, pháp đài rút đi và phần lớn lôi đình bị cắt đứt bên ngoài, giúp Thạch Hạo vượt qua nguy cơ sinh tử. Hắn lập tức nuốt số lôi quang còn lại để luyện thể, đồng thời thả Lôi Trì ra hấp thu một vệt hi quang do dao cầu để lại với ý định luyện kiếm thai hoặc dung nhập vào thân thể. Sau thiên kiếp, một nhóm lão giả đồng loạt lao tới và suýt giao đấu để giành quyền đầu tiên xem xét bí mật của Lôi Trì."}];
